(window.STORIES=window.STORIES||[]).push(...[{"n": 91, "l": "الجزء 65 | تابع أحداث السنه الثانيه من الهجره | غزوة بني قينقاع | اغتيال كعب بن الاشرف | زواج علي من فاطمه", "u": "", "t": "مهر بنت الرسول \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة_والستون\n#تابع_أحداث_السنة_الثانية_من_الهجرة\n#غزوة_بني_قينقاع\n#اغتيال_كعب_بن_الأشرف\n#زواج_علي_من_فاطمة\nاتكلمنا المرة إللي فاتت عن إللي اليهود عملوه في المرأة المسلمة وقتلهم للرجل المسلم،\nقبل ما نعرف رسول الله ﷺ عمل معاهم إيه خلونا نرجع للوراء شوية بعد غزوة بدر بكم يوم \nكان في قبائل اسمهم قبائل غَطَفَان، \nمن قبائل غَطَفان دي كان في قبيلة اسمها بني سُليم، قالوا المسلمين لسه منشغلين بعد حربهم في بدر وأكيد قوتهم تعبانة بعد الحرب ففرصة نهجم على المدينة\nوفعلا جمّعوا قواتهم، في الوقت ده كان وصل لرسول الله ﷺ أخبارهم، فجهز رسول اللهﷺ بسرعة جيش من مائتين راكب وانطلق نحو بني سُليم،\nطبعا بني سليم مكنوش متوقعين إن رسول الله ﷺ ييجي لهم بنفسه، اتفاجؤوا برسول الله ﷺ وهربوا كلهم وتركوا وراءهم خمسمائة بعير\nوطبعا غنمها المسلمون ورجع المسلمون غانمين للمدينة، \nيبقى كده عندنا نصرين للمسلمين وراء بعض\nومع ذلك اليهود لم يتعظوا واعتدوا على المرأة والرجل المسلم\nوصل خبر مقتل المسلم لرسول الله ﷺ، \nراح جامع الصحابة ولابس درع الحرب واتجهزوا للحرب وانطلقوا لبني قينقاع،\nبني قينقاع دخلوا في حصونهم لما عرفوا إن رسول الله ﷺ جاي لهم بجيش، طلب رسول الله ﷺ منهم إنهم يسلموا إللي قتلوا المسلم فرفضوا،\nفحاصرهم، يعني قعد مع جيشه حول الحصون بتاعتهم محدش يدخل ولا يخرج لحد ما اليهود يستسلموا وينزلوا على أمر رسول الله ﷺ،\nفي الموقف ده في فرق واضح جدا بين إللي عمله رسول الله ﷺ لما واحد من المسلمين قُتل،\nوبين موقفه لما أبو جهل قتل سمية وزوجها ياسر، \nلما قُتلا، رسول الله ﷺ لم يأخذ مجموعة من الصحابة وراحوا عشان يقاتلوا أبا جهل زي ما عمل مع يهود بي قينقاع،\nمع إن في الموقفين أكيد هيُقتل ناس من الصحابة، يعني قبيلة أبو جهل كانت هتقاتل المسلمين في مكة،\nوهنا اليهود هيقاتلوا المسلمين وأكيد هيقع منهم قتلى وخصوصا إن يهود بني قينقاع عندهم جيش من سبعمائة جندي، يعني عدد مش قليل خالص،\nفإيه إللي فرق بقى\nالوضع مختلف تماما في الموقفين\nلما قُتلت سمية وزوجها ياسر كان الإسلام لسه في بدايته خالص، وعدد المسلمين كان بسيط جدا وموقفهم ضعيف جدا،\nفمينفعش المخاطرة أبدا بمواجهة المشركين وتعريض حياة القِلة المسلمة للهلاك وبالتالي ضياع رسالة الإسلام عشان ننتقم لشخص مات في سبيل الله،\nلكن دلوقتي لما قُتل واحد من المسلمين في المدينة كان من الطبيعي جدا إن المسلمين يطلبوا القصاص من قاتل أخوهم المسلم؛\nلأن عدد المسلمين أكبر بكثير وقوة الإسلام أكبر ومش بس كده ده المسلمين قضوا على رؤوس المشركين عدوهم الأكبر وإللي وقتلوا وعذبوا إخوانهم في مكة،\nفلازم قبل ما نقول رسول الله ﷺ عمل كذا ونبدأ نعمل زيه نشوف إللي عمله ده كان في أنهي ظروف بالضبط\nاستمر رسول الله ﷺ في حصار بني قينقاع أسبوعين، لحد ما الرعب ملأ قلوبهم ونزلوا على أمر رسول الله ﷺ، \nأمر رسول الله ﷺ إنهم يتكتفوا، وأراد إنه يقتلهم بسبب نقضهم العهد إللي كان بينهم عن طريق قتل المسلم وآذية المرأة المسلمة بكشف عورتها،\nده غير طبعا المخالفات المستمرة خلال السنة ونص إللي فاتوا دول، والتحريض بين المؤمنين وشتمهم لرسول الله ﷺ وشتمهم لربنا،\nفكان لازم وقفة من رسول الله ﷺ ضد اليهود\nجاءه مين\nجاءه عبد الله بن أبي بن سلول إللي كان لسه مُعلن إسلامه من أقل من شهر وكان حليف لبني قينقاع،\nوالحليف يعني يدافعوا عنه وهو يدافع عنهم، ولو تفتكروا إن الأنصار في بيعة العقبة قالوا لرسول الله ﷺ إن في بينهم وبين اليهود عهود وهم هيقطعوها عشان يناصروا رسول الله ﷺ، \nفعبد الله بن أبي بن سلول جاء لرسول اللهﷺ يدافع عن حلفائه اليهود، \nقعد يقول لرسول الله ﷺ أحسن إلى حلفائي، فرفض رسول الله ﷺ لأن جرائمهم كبيرة،\nوهو عمال يتحايل على رسول الله ﷺ أحسن إلى حلفائي،\nوقعد يكرر نفس الكلام لدرجة إنه أدخل يده في جيب الدرع إللي كان رسول الله ﷺ لابسه كأنه مثبته عشان ميتحركش وهو بتحايل عليه،\nفرسول الله ﷺ غضب وقال له: سيبني!!\nفقال عبد الله بن أبي بن سلول:\nلا والله ما أسيبك إلا لما تُحسن إلى حلفائي، سبعمائة رجل منعوني ودافعوا عني ضد كل الناس وإنت عايز تقتلهم كده في طلعة واحدة\nأنا رجل أخاف يحصل حاجة في المستقبل وملقاش حد يدافع عني\nوده أول موقف يُظهر نفاق عبد الله بن أُبي بن سلول، واحد مش بيفكر غير في نفسه، أهم حاجة مصلحته، لكن اليهود إللي بيسبوا الله ورسوله وبيشعلوا الفتن بين المسلمين مش فارق معاه، \nمعندوش انتماء إلا لنفسه ومصالحه وخلاص، ماشي بمنطق ناس كتير للأسف : أنا ومن بعدي الطوفان\nرسول الله ﷺ قال له : خلاص خدهم وقَبِل منه إنه يفتديهم بالمال بشرط إنهم يطلعوا خارج المدينة ومحدش يقعد منهم فيها،\nفوافقوا وراحوا منطقة اسمها أَذرُعات بالشام وقعدوا هناك، يُقال إنهم هلكوا جميعا بعدها بفترة قصيرة والله أعلم بصحة الخبر ده\nوبكده انتهت قصة بني قينقاع مع رسول الله ﷺ.\nخدوا بالكم إن رسول الله ﷺ ماخدش خطوة إخراج يهود بني قينقاع إلا بعد ما كان متطمئن إن إقتصاد المدينة مش هيقع\nفاكرين لما قلنا إن يهود بني قينقاع كانوا هم إللي ماسكين سوق المدينة ومتحكمين في تجارة المدينة، وكان رسول الله ﷺ عمل سوق للمسلمين،\n فلما بقى سوق المسلمين قوي كان من السهل الاستغناء عن سوق بني قينقاع بدون مايكون في أي ضرر على المسلمين\n☆ملحوظة: \nسبب خروج رسول الله ﷺ لغزوة بني قينقاع إللي قلنا عليه وهو قصة المرأة المسلمة وقتل الصحابي المسلم، كل الروايات إللي ذكرت الحدث فيها ضعف، لكن مفيش أي رواية صحيحة ثانية بتتكلم عن سبب غزوة بني قينقاع،\nفأنا قلتها لأن هي الرواية الوحيدة في سبب الغزوة، وهي الرواية الوحيدة إللي العلماء بيذكروها\nلكن قصة غزوة بني قينقاع كلها صحيحة وخروج رسول الله ﷺ وإللي عمله عبد الله بن أبي بن سلول كل ده صحيح\n◇السؤال بقى إللي بيطرح نفسه هنا، ليه رسول الله ﷺ وافق على طلب عبد الله بن أُبي بن سلول \nبالنسبة لرسول الله ﷺ عبد الله بن أبي بن سلول كان لسه مسلم جديد، فكان محتاج إنه يتألف قلبه ويعامله بالحسنى عشان يتألف قومه كمان، \nومكنش لسه خطره كمنافق ظهر فكان رسول الله ﷺ يظن فيه إنه ممكن يحسن إسلامه،\nورسول الله ﷺ بشر يا جماعة لا يعلم الغيب إلا إللي ربنا بيُطلعه عليه، فهو بيعمل إللي بيشوفه مناسب لمصلحة الإسلام ودولة الإسلام،\nولو حصل خطأ بسيط يأتي الوحي بتعديل المَسار، زي ما شفنا في قضية فِداء الأسرى\nوبما إننا بنتكلم عن اليهود يبقى لازم نتكلم عن اليهودي كعب بن الأشرف\nكعب بن الأشرف كان من يهود بني النُّضَيْر، بعد غزوة بدر اتغاظ جدا من نصر المسلمين، فقعد يهجو رسول الله ﷺ والمسلمين ويمدح في عدوهم ويحرض المشركين على قتال المسلمين،\nومش بس كده ده خرج من المدينة وراح لقريش في مكة وقعد يقول أشعار يرثي ويبكي فيها سادات مكة إللي ماتوا وده طبعا خلى أهل مكة يغلوا من الغيظ ويحقدوا أكثر على المسلمين\nولما قريش سألوه مين فينا إللي على حق، محمد ودينه ولا احنا قال لهم :إنتم \nيعني بيقول إن الشرك بالله أفضل من التوحيد إللي رسول الله ﷺ جاء به،\nفأنزل الله :\n\"أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا هَٰؤُلَاءِ أَهْدَىٰ مِنَ الَّذِينَ آمَنُوا سَبِيلًا\"\nيسكت بقى بعد إللي عمله ده كله\nلأ، رجع للمدينة للمدينة وبدأ يتطاول على نساء الصحابة بأشعاره،\n☆ والشعر ساعتها كان زي القنوات الفضائية عندنا كده،\nشوفوا لما تحصل أي حاجة وتلاقوا القنوات الفضائية كلها بتتكلم،\nوصفحات التواصل كلها بتنقلها، أهه الشعر كان هو القنوات الفضائية وشبكة التواصل الاجتماعي عندهم،\nحتى رسول الله ﷺ استعمل الشعر في حربه ضد أهل مكة،\nوكان بيفرح لما شاعر بيسلم، \nولما أسلم كعب بن مالك وعرّف رسول الله ﷺ بنفسه، رسول الله ﷺ قال له: الشاعر؟!!!\nفكعب بن مالك بيقول إنه عمره ما ينسى رد فعل رسول الله ﷺ لما سمع اسمه، لأن كده رسول الله ﷺ كسب في صفه قناة إعلامية تدافع عن الإسلام، \nوكان حسان بن ثابت وهو من الأنصار شاعر وبقى اسمه شاعر النبي، فكان بيهجو قريش وبيرد على شعرهم بشعره،\nومن شعره في وصف رسول الله ﷺ انه قال:\nوأَحسنُ منكَ لم ترَ قطُّ عيني ** وَأجْمَلُ مِنْكَ لَمْ تَلِدِ النّسَاءُ\nخلقتَ مُبرأً منْ كلّ عيبٍ **  كأنكَ قدْ خلقتَ كما تشاءُ\nومن شعره :\nهجوتَ محمداً، فأجبتُ عنهُ ** وعندَ اللهِ في ذاكَ الجزاءُ\nفَإنّ أبي وَوَالِدَهُ وَعِرْضي ** لعرضِ محمدٍ منكمْ وقاءُ\nفتخيلوا بقى لما واحد يطلع يتكلم في عرض الصحابيات بشعره والشعر ده ينتقل في كل مكان، يعني احنا لو حد غلط فينا وقال علينا كلمة بسيطة بنبقى زعلانين جدا،\nفما بالكم لو كان الكلام في العرض، وأصلا كل إللي بيعمله ده مخالف للعهد إللي بينه وبين رسول الله ﷺ \nرسول الله ﷺ عرف باللي كعب بن الأشرف بيعمله، فقال رسول الله ﷺ : من لكعب بن الأشرف فإنه آذى الله ورسوله؟!!\nيعني مين يقتله ويخلصنا من شره، فقام محمد بن مَسلمة وأبو نائلة وكانا من الأنصار فقالا احنا نقتله يا رسول الله لكن ائذن لنا أن نقول شيئا، يعني نكذب في الكلام،\nفأذن لهما رسول الله ﷺ،  وهنا الكذب يجوز لأنه كذب على الأعداء بما فيه مصلحة للمسلمين\nفذهبا لكعب بن الأشرف وقالا له : \nإن الرجل ده =رسول الله يعني=كل شوية يطلب صدقات صدقات، واحنا مبقاش معانا، فاحنا عايزينك تساعدنا في الموضوع فجئنا نستلف منك\nفقال لهم: والله لتزهقوا منه إنتم لسه شفتم حاجة\nوإيه إللي مصبركم عليه أصلا\nفقال له محمد بن مَسلمة:\nاحنا عايزين نفضل معاه لحد ما نشوف هيوصل لإيه في النهاية وبعدين نحدد هنعمل إيه بعد كده\nفقال لهم: طيب خلاص ارهنوني نساؤكم\nيعني يقصد أنه يعطيهم المال مقابل إن زوجات أبو نائلة ومحمد بن مسلمة يكونوا عنده رهائن،\nفقالا له: إنت عايزنا نرهنك نساءنا وانت أجمل العرب وبعدين نساءنا يُفتنوا بك لا مش هينفع\nفقال كعب: خلاص ارهنوني أبناءكم \nفقالا : نرهنك أبناءنا ولما يكبروا العرب يعيّروهم إنهم اترهنوا عشان شوية شعير\nلكن ممكن نرهنك اللّأْمة عادي \nواللأمة إللي هي أداة الحرب يعني السيف والدرع، وده كان تصرف ذكي جدا من محمد بن مسلمة،\nتخيلوا لو كان جاء بالسيف معاه من غير داعي كان كعب بن الأشرف هيشك إن في حاجة غلط، \nلكن دلوقتي بقى طبيعي جدا إنهم يأتوا بالسيوف، لأنهم جايين يرهنوها،\n اتفقوا على يوم يتقابلوا فيه وكان الميعاد ليلا، فلما جاءاه وندهوا عليه وقام عشان ينزل لهم، قالت له زوجته وكان لسه متزوج حديثا إنت رايح فين الساعة دي\nأنا أسمع صوتا يقطُر منه الدم، يعني أنا سامعة صوت بينقط دم\nفقال لها : متقلقيش، ده أخويا محمد بن مسلمة، ورضيعي أبو نائلة\nيعني أخويا من الرضاعة، فلما نزل لهم وشموا ريحته، قالوا له : إيه الريحة الجميلة دي \nفقال لهما : عندي أجمل العطور\nفقال له محمد بن مسلمة تسمح لي أشم رأسك\nفقال له كعب : أكيد، فلما نزل رأسه راح ماسكه محمد بن مسلمة وقال دونكم عدو الله فاقتلوه، فاجتمعوا عليه فقتلوه\n☆طبعا ممكن ييجي في ذهننا دلوقتي إنه كده يُعتبر قُتل غدر\nأي حد يستحق القتل لا يُقال عنه إنه قُتل غدرا\nكعب بن الأشرف يستحق القتل بسبب إللي عمله ده كله،\nوفي فرق كبير جدا بين موقف بني قينقاع وإللي حصل معاهم وبين موقف كعب بن الأشرف إللي كان من بني النُّضير،\nرسول الله ﷺ عاقب بني قينقاع كلهم لأنهم كانوا بيعادوا المسلمين وبيظهروا العداء علنا وكلهم متفقين على كده،\nفكانوا يستحقوا إن رسول الله ﷺ يخرج لهم في جيش،\nبعكس كعب بن الأشرف كان رجل واحد فقط هو إللي أظهر العداء ونقض العهد وعمل الحاجات إللي قلنا عليها،\nفكان يجب قتله،\nولكن لو كان رسول الله ﷺ خرج له بجيش كان ممكن يهود بني النّضير تأخذهم الحمية ويقاتلوا رسول الله ﷺ وندخل في حرب ملهاش لازمة دلوقتي،\nفأفضل حل إن يتم اغتيال كعب بن الأشرف\nوبعد قتل كعب بن الأشرف جاء يهود بني النضير لرسول الله ﷺ عشان يقولوا له إنهم على العهد إللي بينهم\nفالوضع دلوقتي استقر نسبيا من ناحية اليهود، لأنهم شافوا إللي حصل مع بني قينقاع وكعب بن الأشرف،\nيعني وصلت لهم رسالة باختصار كده إن الناس دي =رسول الله ﷺ والصحابة= مبتهزرش فخدوا بالكم\nمن الأحداث إللي حصلت في السنة الثانية من الهجرة زواج علي بن أبي طالب من فاطمة بنت رسول الله ﷺ، \nيُقال إن الزواج ده كان في شهر شوال ويقال إنه كان في ذي الحجة،\nاحنا مش هيهمنا التاريخ أد ما يهمنا الحدث نفسه\nفاطمة بنت رسول الله ﷺ أصغر بناته وأحبهن إلى قلبه، كانت أكثر الناس شبها بكلام رسول الله ﷺ، \nاتولدت قبل البعثة زي ما قلنا في البداية، وشافت الأذى إللي تعرض له رسول الله ﷺ، \nوهي إللي نظفت أمعاء البعير من على ظهر رسول الله ﷺ لما رماه عليه عقبة بن أبي معيط لما كان ساجد عند الكعبة،\nخطبها أبو بكر الصديق رضي الله عنه فلم يوافق رسول الله ﷺ، \nوخطبها عمر بن الخطاب فلم يوافق عليه، بسبب فارق السن الكبير إللي كان بينهم، فالأصل إن المرأة تأخذ القريب لها في السن عشان يكون في تكافؤ بينهم،\nواحنا اتكلمنا قبل كده عن السبب إللي جعل رسول الله ﷺ يتزوج من عائشة مع إن فرق السن بينهم كبير فمش هعيد،\nممكن ترجعوا للموضوع في الجزء التاسع والثلاثين\nجاءت مولاة لعلي بن أبي طالب وقالت له إن الناس بدأوا يطلبوا فاطمة للخطبة، فقالت له : إيه إللي يمنعك من إنك تروح وتخطبها من رسول الله ﷺ \nفقال لها : وهو أنا عندي حاجة أتزوج بها\nيعني أنا فقير ومعنديش حاجة أدفعها كمهر،\nفقالت له : لو إنت روحت لرسول الله ﷺ هيزوجها لك\nفراح لرسول الله ﷺ وقعد قصاده ومعرفش يتكلم\nرسول الله ﷺ كانت له هيبة، فهو دلوقتي جاي يطلب إيد بنته إللي بيحبها وبيخاف عليها، وهو فقير معندوش حاجة فهيتكلم إزاي\nفرسول الله ﷺ سأله: إنت جاي عايز حاجة؟!\nفسكت علي رضي الله عنه \nفقال له رسول الله ﷺ: لعلّك جئت تخطب فاطمة؟!\nفقال علي بن أبي طالب: نعم\nفقال له رسول الله ﷺ: وإنت عندك شيء تقدمه لها مهر؟!\nفقال له علي رضي الله عنه:\nلا والله يا رسول الله\nفقال له رسول الله ﷺ : أنا كنت أعطيتك درع تتسلح بها، عملت فيها إيه؟\nفقال علي: والله يا رسول الله دي درع متحطمة ميجبش ثمنها أربعة دراهم\nفقال له رسول الله ﷺ: أنا زوّجتك فاطمة بالدرع دي\nوتزوجت فاطمة بعلي بن أبي طالب وكان عمرها ثمانية عشر عاما، وكان علي بن أبي طالب حوالي ثلاثة وعشرين عام،\nفاطمة رضي الله عنها لما رسول الله ﷺ أخبرها بإن علي رضي الله عنه تقدم لخطبتها وأخبرها إن مهرها كان درع مقلتش مثلا إزاي أكون بنت رسول الله ويكون مهري درع  ثمنه أربعة دراهم \nوالدرع ده كان ثمنه في الحقيقة 400 درهم والدرهم الواحد يساوي ثلاثة جرام من الفضة، بحسبة بسيطة كده يبقى الأربعمائة درهم يساووا حوالي 3600 جنيه مصري\nيعني مهر بنت رسول الله ﷺ سيدة نساء أهل الجنة وسيدة نساء العالمين كان 3600 جنيه،\nولو كان المهر العالي حاجة حلوة كان رسول الله ﷺ أمر بيه زي ما عمر بن الخطاب رضي الله عنه قال:\n\"لا تُغَالوا صداق النساء فإنها لو كانت مَكرُمة في الدنيا أو تقوى عند الله كان أوْلَاكم وأحقّكم بها محمد ﷺ\"\nأما جهازها إللي رسول الله ﷺ جهزها بيه فكان قطيفة، ثوب يعني ألبسه رسول الله ﷺ لفاطمة، وقِربة، بلغة عصرنا الإزازة إللي بيتحط فيها ماء،\nووسادة من جلد حشوها نبات رائحته حلوة،بس كده\nما هو يا جماعة رسول الله ﷺ قال :\nمالي وللدنيا إنما مثلي ومثلُ الدُّنيا كراكبٍ استظلَّ تحت شجرةٍ ثم راحَ وتركها \nزي لما بنسافر بلد تانية كده يومين تلاتة، هل بناخد كل حاجاتنا إللي في الشقة معانا ولّا بناخد إللي بيكفينا في الرحلة؟\nأهه هي دي الدنيا بالنسبة للآخرة، وكان طبيعي إن السيدة فاطمة إللي اتربت في بيت النبوة وأخلاقها تُشبه أخلاق رسول الله ﷺ جدا إن يكون زواجها سهل ميسور مفهوش أي صورة من صور متاع الدنيا الزائل،\nوانضرب بها المثل في زواجها اليسير المهر، القليل المؤنة\n☆طيب هل المفروض إننا نعمل زي علي وفاطمة رضي الله عنهما في موضوع الزواج\nشوفوا، \nعامّة الصحابة كانوا فقراء، وحتى بيت رسول الله ﷺ كان بيت فقير،\n يعني كان ممكن يعدي على رسول الله ﷺ أيام من غير ما يأكل، فكان طبيعي إنهم يتزوجوا عالحال إللي هم فيها،\nوكذلك في عصرنا فالمرأة تتزوج من صاحب الخلق والدين إللي يتناسب مع حالها ووضعها، لأن التكافؤ بين الزوجين مطلوب\nوطبعا كل ما خففنا في تكاليف الزواج كان الزواج والمرأة نفسها مباركة، يعني موضوع إن واحدة تجيب ستين فوطة وثلاثين ملاية سرير، ومش عارفة كم طقم حلل وكم طقم كاسات وكوبيات و...و...\nده غير بقى الفرح وإللي بيحصل فيه والطلبات إللي بتتطلب من الشخص إللي بيتقدم وإزاي تكون أقل من بنت خالها ولا أختها ولا بنت طنط عفاف ولا طنط فتكات والكلام إللي يخلي البنات تعنس أو تتزوج أي واحد والسلام بسبب التعقيدات دي\nكل ده مكنش من هدي رسول الله ﷺ ولا من هدي الصحابة،\nحتى عمر بن الخطاب كان بيقول زي ما قلنا من شوية:\n\"إِيَّاكُمْ وَالْمُغَالاَةِ فِى مُهُورِ النِّسَاءِ فَإِنَّهَا لَوْ كَانَتْ تَقْوَى عِنْدَ اللَّهِ أَوْ مَكْرُمَةً عِنْدَ النَّاسِ لَكَانَ رَسُولُ اللَّهِ ﷺ  أَوْلاَكُمْ بِهَا، \n مَا نَكَحَ رَسُولُ اللَّهِ ﷺ  شَيْئًا مِنْ نِسَائِهِ وَلاَ أَنْكَحَ وَاحِدَةً مِنْ بَنَاتِهِ بِأَكْثَرِ مِنِ اثْنَىْ عَشَرَةَ أُوقِيَّةً وَهِىَ أَرْبَعُمِائَةِ دِرْهَمٍ وَثَمَانُونَ دِرْهَمًا، \nوَإِنَّ أَحَدَهُمْ لَيُغَالِى بِمَهْرِ امْرَأَتِهِ حَتَّى يَبْقَى عَدَاوَةً فِى نَفْسِهِ فَيَقُولُ : لَقَدْ كُلِّفْتُ لَكِ عَلَقَ الْقِرْبَةِ\"\nيعني بلغة عصرنا يقعد يعايرها ويقول لها دفعت فيكِ دم قلبي\nحتى إن واحدة من المسلمات الصحابيات اسمها أم سُليم لما جاءها أبو طلحة يتزوجها وكان رجل كافر، قالت له :\nواحد زيك محدش يرفضه، ولكن إنت رجل كافر وأنا امرأة مسلمة، فقال لها : طيب إيه هو مهرك ؟\nفقالت له : مهري الإسلام، يعني لو أسلمت هتزوجك،\nوفعلا أسلم أبو طلحة وتزوج أم سُليم، فكان مهرها أغلى مهر في الإسلام،\nوكان رسول الله ﷺ يُزوج الصحابة بأجزاء القرآن إللي حافظينها لو كانوا فقراء ومكنش عندهم أموال يقدموها مهر،\nكل ده حلو وجميل خالص، لكن ينفع احنا نعمل كده\nلو تأكدنا إن الشخص المتقدم ده فعلا فعلا فعلا على دين وخُلق وراااجل بجد\nمفيش مشكلة إننا نعمل كده عادي واحنا الكسبانين، \nلكن ميكونش مجرد اسمه يخليه ضمن دائرة الرجال لكن هو لا يتعدى إنه ذَكر ونقول هنزوجك باللي معاك من القرآن \nفرقوا يا جماعة الله يكرمكم\nوطبعا ده بجانب المهر المتفق عليه؛ لأن المهر من شروط صحة الزواج\nالمهم،\nكانت إيه أحوال مكة في الوقت ده؟\n طبعا كانوا مقهورين من إللي حصل لهم في بدر\nوكان صفوان بن أمية إللي اتكلمنا عنه قبل كده بيحاول يشوف خطط وبيرتب إزاي ينتقم من المسلمين،\nوكان من الناس المقهورة أبو سفيان بن حرب إللي أصبح سيد مكة بعد موت سادات مكة كلهم،\nفقال إنه لازم يعمل أي حاجة ينتقم بها من المسلمين،\nراح مجمع مائتين راكب وقرر إنه يفاجئ المدينة بهجوم،\n زي غارة كده\nوصل أبو سفيان لأطراف المدينة وهجم عليها وحرق شوية نخيل، وقتل واحد من الأنصار هو وواحد من حلفائه كانوا في البستان بتاعهم،\nوكل ده بالليل، وراحوا طالعين جري وهربوا ناحية مكة،\nوصل الخبر لرسول الله ﷺ راح مجمع على طول مائتين واحد من الصحابة وطلعوا وراء أبو سفيان،\nحاول رسول الله ﷺ يلحق به لكن معرفش، وكان أبو سفيان والناس إللي معاه بيرموا المتاع والأكل إللي معاهم عشان يتخففوا من الوزن فيقدروا يهربوا،\nوكان معاهم أكل اسمه السّوِيق وده كان أكثر أكل معاهم فقعدوا يرموه وغَنِمه المسلمون،\nفعشان كده الغزوة دي اتسمت غزوة السّوِيق\nفي السنة الثانية من الهجرة ومع أول عيد أضحى للمسلمين ضحّى رسول الله ﷺ بكبشين بعد صلاة العيد،\nخروفين يعني، وكان رسول الله ﷺ كل ما بيضحي كان بيضحي بخروفين، واحد عنه وعن أهل بيته، \nوواحد عن من لم يضحِّ من أمته من إللي شهدوا بالتوحيد والبلاغ لرسول الله ﷺ، \nودي كانت أهم أحداث السنة الثانية من الهجرة،\nإيه إللي حصل في السنة الثالثة من الهجرة ، \nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 92, "l": "الجزء 66 | حياة رسول الله صلى الله عليه وسلم مع الصحابه الجزء الأول | قصة قاتل المائة نفس", "u": "", "t": "متضربوش عيالكم عشان هايفتكرو الوحش منكم قبل الحلو \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة_والستون\n#حياة_رسول_الله_مع_الصحابة_الجزء_الأول\n#قصة_قاتل_المائة_نفس\nاتكلمنا الأجزاء الأخيرة إللي فاتت عن الغزوات والسرايا إللي رسول الله ﷺ عملها وشوفنا تصرفاته خارج المدينة أو بمعنى أوضح مواقفه مع غير المسلمين،\nعايزين نعرف بقى حياة رسول الله ﷺ كانت عاملة إزاي مع الصحابة، هل كان طول اليوم بيخطط للغزوات،\nولّا كان بيقعد يخطب في الصحابة طول اليوم وحياته كلها جد ومفيش فيها أي مزاح مع أصحابه خالص ولا كانت حياته اليومية عاملة إزاي\nإن شاء الله خلال الجزء ده هنشوف جانب من حياة رسول الله ﷺ بعيد عن الغزوات والحرب،\nطبعا مش هقدر أجيب كل المواقف والأحداث بالتفصيل، \nلأنها كثيرة جدا\nفكل كم حلقة كده إن شاء الله نتكلم عن حياة رسول الله ﷺ اليومية مع أصحابه بصفة عامة \nرسول الله ﷺ مع إنه رسول الله ومطلوب يَعظ الناس ويذكّرهم الآخرة لكن مكنش طول اليوم بيقول لهم مواعظ، \nالصحابة بيقولوا إن رسول الله ﷺ كان يتخوّلنا بالموعظة مخافة السآمة علينا، \nيعني كل كم يوم مثلا يقول لهم موعظة يذكرهم فيها بالله عشان نفوسهم لا تمل،\nوعبد الله بن مسعود الصحابي إللي قتل أبو جهل كان بيقول اتكلموا وانصحوا الناس لما تلاقوهم مُقبلين عليكم وعايزين يسمعوا منكم، لكن لو لقيتوهم مش حابين أو كارهين بلاش تكلموهم،\nفده كان منهج رسول الله ﷺ والصحابة في الموعظة، كل كم يوم موعظة، ومكنتش الموعظة نمط واحد، \nيعني مش هو هو نفس الكلام بيكرره بنفس الطريقة،\nلأ كان بينوع ﷺ ، مش بس بيقول كلام الصحابة بيسمعوه،\nلأ، كان كمان بيستخدم حاسة البصر عشان يكون الكلام له تأثير أوقع في قلوبهم. \n◇مثال :\nمرة رسول الله ﷺ كان قاعد مع الصحابة، فراح راسم لهم في الأرض خط طويل وحول الخط ده رسم خطوط صغيرة \n¡ ¡ ¡ | ¡ ¡ ¡ وبعدين قال لهم : الخط الطويل ده هو صراط الله  المستقيم،\nوالخطوط الصغيرة دي هي سُبل الشيطان إللي بيزيّنها للإنسان عشان يمشي فيها، وعلى كل طريق من الطرق دي في شيطان بيزين الطريق ده للناس،\nفاللي هيمشي في طريق ربنا المستقيم هيوصل له، وإللي هيتبع سبل الشيطان المتزينة دي هيضل\nطريق ربنا هو القرآن والسنة بفهم الصحابة والتابعين وتابعي التابعين، أي حد يقول أو يعمل عكس إللي هم عملوه يبقى هو كده دخل في سبيل من سُبل الشيطان\n\"وَأَنَّ هَٰذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِ\"\nومرة تانية كان يخليهم يشغّلوا خيالهم ويربط الخيال بأمور الدين ويقول لهم الموعظة على هيئة سؤال،\n◇مثال : \nسأل رسول الله ﷺ الصحابة في مرة، لو واحد عنده نهر عند باب بيته بيغتسل منه خمس مرات في اليوم هل هيبقى على جسمه أي وَسَخ؟\nقالوا : لأ يا رسول الله\nفقال لهم رسول الله ﷺ: والصلاة برده نفس الموضوع، ربنا بيمحو الخطايا بالصلاة، \nوده عن طريق إن ربنا بيضع سيئات الإنسان على ظهره وهو بيصلي فكل ما ركع أو سجد تتساقط سيئاته.\nومرة ثالثة كان يعظهم بإنه يحكي لهم قصة من قصص الأمم السابقة زي قصة قاتل المائة نفس،\n◇قال رسول الله ﷺ للصحابة : \nكان في رجل في الأمم السابقة قتل تسعة وتسعين نفس،\nوفي يوم من الأيام لقى نفسه عايز يتوب، فسأل الناس عن أعلم أهل الأرض،\nفالناس دلّوه على راهب، والراهب ده هو الشخص المنقطع عن الناس لعبادة الله، فهم ظنوا إن مادام الرجل ده ظاهر عليه العبادة يبقى أكيد عنده علم،\n☆وده يدل إن القصة حصلت بعد رفع عيسى عليه السلام، لأن الرهبانية لم توجد إلا بعد رفع عيسى، ربنا بيقول:\n\"وَرَهْبَانِيَّةً ابْتَدَعُوهَا\" \nفراح له وكلمه وقال له:\nأنا قتلت تسعة وتسعين نفس، فهل لي من توبة\nفالراهب العابد إللي ميعرفش يعني إيه معصية ناهيكم عن قتل نفس واحدة، فلما واحد يقول له أنا قتلت تسعة وتسعين نفس  هيبقى مصدوم إزاي\nزي مثلا لما واحد يكون عفيف عمره ما اتكلم مع بنت وييجي واحد يقول له أنا زنيت تسعة وتسعين مرة، تخيلوا صدمته هتكون إزاي\nفكانت صدمة الراهب شديدة فقال له بكل تلقائية :\n لأ ملكش توبة، توبة إيه بعد ما قتلت تسعة وتسعين نفس\nفالرجل اتغاظ واتضايق راح قاتل الراهب ومكمّل به المائة\n☆لو ركزتم في حياتكم هتلاقوا إن الموقف ده بيتكرر معانا كتييير من غير ما ناخد بالنا،\nواحدة ولّا واحد يبقى نفسه يتوب وفعلا ياخد خطوة على الطريق ويبدأ يدوّر على الطريق الصحيح عشان يتوب ، \nفربنا يضع في طريقه ابتلاء عشان يختبر صدقه، فتحصل له مصيبة أو كارثة، \nيضع في طريقه واحد مُنفر معندوش علم زي الراهب ده كده يصده عن سبيل الله،\nفلو هو صادق هتلاقيه مكمل طريقه بغض النظر عن الناس المنفرة دي أو المشاكل إللي بتحصل له،\nلكن لو مكنش صادق في توبته هتلاقيه قعد يتحجج ويقول أنا أول ما قلت هبقى كويس، لقيت المصايب نازلة على دماغي، خلاص خليني في إللي أنا فيه،\nأو يقول ده الناس كرهتني في الدين فبعدت عنه\nوالمسكين مش فاهم إن ده اختبار من ربنا له وهو كده سقط فيه\n\"أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لا يُفْتَنُونَ \"\n يا ترى بقى الرجل ده استسلم وقال خلاص أنا عملت إللي عليّ وأنا كده ربنا مش قابلني ولّا عمل إيه\nالرجل قاتل المائة نفس ده قعد فترة من الزمن الله أعلم بها وبعدين حَنّ تاني للتوبة، فسأل عن أعلم أهل الأرض، فدلّوه على عالم،\nفراح له وكلمه وقال له: أنا قتلت مائة نفس هل لي من توبة\nفقال له العالم : ومين يمنع عنك التوبة، باب التوبة مفتوح لأي إنسان، لكن اخرج من بلدك وروح بلد كذا فهي فيها رجال بيعبدوا الله فاعبد الله معهم\n☆وده الفرق بين إللي عنده علم وإللي بيتكلم بجهل، هو فهم مشكلة الرجل ده فين، مشكلته في بيئته، \nماهو لو كان الناس إللي حوله صالحين وبيأخذوا على يد الظالم القاتل مكنش وصل لقتل مائة نفس،\nوممكن إن الناس خايفين منه، فكده محدش هيقدر يقول له افعل ولا تفعل، \nلكن لما يروح بأرض غريبة محدش يعرفه فيها الناس هتعامله بأسلوب مختلف وخصوصا لو كانوا صالحين\nفالرجل ده كان صادق في توبته فعلا، أول ما العالِم قال له اخرج من بلدك روح بلد تانية، على طول اتجه للبلد دي،\nمقعدش بقى يفكر طيب ومكانتي بين الناس وأكل عيشي وبلدي و...و...\nهو عايز يوصل لربنا من قلبه بجد فبالنسبة له الحاجات دي مش مهمة، وهو في الطريق جاءه أجله\nده لسه معملش حاجة، لسه متعلمش إزاي يعبد ربنا ولا يكفر عن غلطته في قتل المائة نفس ودلوقتي هيموت\nعايزاكم تتخيلوا شكل الرجل ومشاعره وهو بيصارع الموت والكلام ده في ذهنه وهو بيزحف بصدره ناحية الأرض إللي فيها الناس الصالحين عايز يعمل أي حاجة تثبت لربنا إنه صادق في توبته \n☆والإنسان لو كان صالح روحه بتخرج بسهولة جدا زي قطرة الماء إللي بتنزل من إزازة المية،\nوتقوم ملائكة الرحمة إللي وجوههم عاملة زي الشمس واخدة روحه ومكفناها بكفن من الجنة وبتطلع به للسماء فكل ما يعدوا على مجموعة من الملائكة يقولوا إيه الريحة الجميلة دي،\n فملائكة الرحمة تقول دي روح فلان بن فلان، وتتفتح لها أبواب السماء لحد السماء السابعة فربنا يقول :\n اكتبوا كتاب عبدي في عليِّين، يعني اجعلوا كتاب العبد ده في دفتر المؤمنين،\nوأعيدوه إلى الأرض، فتأخذه الملائكة ويرجعوا روحه لجسده، فيأتيه الملكان منكر ونكير ويقعدوه ويسألوه :من ربك ؟ فيقول: ربي الله! مادينك؟ فيقول :ديني الإسلام!\nمن نبيك أو ما هذا الرجل الذي بُعث فيكم؟\nفيقول : هو رسول الله ﷺ، فينادي مناد من السماء إن العبد ده صادق فافرشوا له من الجنة وألبسوه من الجنة وافتحوا له بابا من الجنة،\nويأتيه رجل شكله جميل ريحته حلوة ويقول له : أبشر باللي يفرحك، فيسأله: إنت مين، فوجهك الوجه الذي يجيء بالخير\nفيقول له : أنا عملك الصالح\nفيقول : رب أقم الساعة رب أقم الساعة.\nفجاءت ملائكة الرحمة دي \nعشان تقبض روح الرجل إللي قتل مائة نفس وإللي خرج تائب، وفي نفس الوقت جاءت ملائكة العذاب إللي اتكلمنا عنهم قبل كده لما قبضوا روح أبا لهب ومشركي قريش، فمش هعيد وصفهم تاني\nملائكة العذاب شايفة إن الرجل يستحق العذاب لأنه لسه معملش حاجة تكفر عن سيئاته، \nوملائكة الرحمة شايفة إنه لأ الرجل خرج تائب وكان ناوي فعلا التوبة، \nفأرسل الله عز وجل مَلك عشان يفصل بينهم وقال لهم:\nقيسوا الأرض، يعني شوفوا الرجل مات فين وشوفوا هو كان أقرب لأنهي أرض،\nأرض الصالحين ولّا أرضه إللي خرج منها، فقاست الملائكة المسافة لقوه أقرب لأرض الصالحين، \nوفي رواية إن ربنا أمر أرض الصالحين أن تتقارب، وأرض الرجل إللي خرج منها أن تتباعد، \nفلما قاسوا المسافة لقوه إنه كان اقرب لأرض الصالحين بشبر، فأخذته ملائكة الرحمة\n◇خدوا بالكم إن الصحابة بشر زينا بالضبط، بيقعوا في الخطأ وكانوا بيعملوا معاصي برده، فرسول الله ﷺ بيعلمهم من خلال القصة دي إن مهما الإنسان أخطأ أو عمل معاصي أو حتى كبائر فهو يتوب إلى الله ويرجع، وربنا هيتوب عليه ويغفر له،\nوعلى الرغم  من إن الصحابة غير معصومين وكانوا بيقعوا في الخطأ فهم كلهم عُدُول،\n يعني كل كلامهم وأخبارهم ثقة، فمحدش فيهم بيتعمد الكذب في شهادته، ولا يتعمد الكذب على رسول الله ﷺ\n☆إيه ده يعني المنافقين عُدول\nالمنافقين أصلا مش صحابة، ومحدش فيهم روى أي حديث عن رسول الله ﷺ،  الصحابي هو إللي آمن برسول الله ﷺ وقابله ولو مرة ومات ولم يرتد عن الإسلام،\nأما المنافقين فهم لم يؤمنوا برسول اللهﷺ من الأساس\n◇بمناسبة بقى الكلام عن قصص بني إسرائيل ممكن ييجي في بالنا سؤال،\nاحنا عارفين إن الإسرائيليات هي القصص والأخبار إللي المسلمين بينقلوها عن بني إسرائيل واتكلمنا عنها وعن حكمها بالتفصيل في قصص الأنبياء،\nالسؤال بقى : هل أحاديث رسول الله ﷺ إللي فيها قصص عن بني إسرائيل تُعتبر من الإسرائيليات ولّا لأ\nأحاديث رسول اللهﷺ مش من الإسرائيليات، لكنها من الأخبار إللي جاء بها الإسلام،\nفكل حديث صحيح عن رسول الله ﷺ فيه قصة من قصص بني إسرائيل هو من الوحي،\nيعني قصة حقيقية حصلت فعلا فيجب علينا تصديقها،\nبعكس قصص الإسرائيليات التي لا نصدقها ولا نكذبها\nكان من منهج رسول الله ﷺ مع الصحابة لما بيقعوا في الخطأ إنه بيوجههم على طول للحل،\n◇مثال:\nواحد من الصحابة قَبّل امرأة لا تحل له، فجاء لرسول الله ﷺ وأخبره باللي عمله ده، وكان وقت صلاة فصلى رسول الله ﷺ وصلى الرجل معاه ومع الصحابة، \nوبعد الصلاة الرجل أعاد عليه الموضوع فقال له رسول الله ﷺ: إنت صليت معانا؟\nفقال له الرجل : نعم صليت، فقال له رسول الله ﷺ: \nخلاص ربنا غفر لك، وأنزل الله :\n\"وَأَقِمِ الصَّلاةَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِنَ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ\"\n☆نقطة مهمة \n الكلام ده \n خاص بالصغائر وكمان مع عدم الإصرار عليها \nيعني الصحابي إللي قبّل امرأة ده عمل حسنات بعدها مسحت الذنب الصغير إللي عمله ده وهو لم يكرره مرة ثانية،\nلكن لو كان استمر على فعل الذنب ده حتى لو كان من الصغائر يتحول لكبائر على طول\nأما لو الإنسان وقع في كبيرة فيطهرها ويمسحها التوبة الصادقة أو إقامة الحد الشرعي، \nيعني لو واحد وقع في الزنا ميقولش أنا الصلاة تطهر الزنا ده، \nلازم توبة صادقة من القلب وعمل طاعات كتير جدا عشان يتمسح عنه كبيرة الزنا\nفرسول الله ﷺ مقعدش بقى يقول له إنت إزاي تُقبل امرأة لا تحل لك، ومش مكسوف من نفسك و...و...\nمن غير كلام ملوش لازمة وجهه للحل على طول، \nوشوفوا القصة دي كمان إزاي رسول الله ﷺ اتعامل مع خطأ تاني لواحد من الصحابة،\nصحابي اسمه معاوية بن الحكم السُّلَمي كان بيصلي المسلمين في صلاة من الصلوات ،فعطس واحد من الصحابة وهو بيصلي، فمعاوية بن الحكم وهو في الصلاة راح قايل له: يرحمك الله،\nفالصحابة قعدوا يبصوا له جامد مصدومين من إللي عمله، إنت بتتكلم في الصلاة\nفراح قايل لهم إنتم بتبصوا لي كده ليه\nكل ده في الصلاة\nفالصحابة قعدوا يخبطوا على أفخاذهم عشان يسكت فسَكت، بعد الصلاة، رسول الله ﷺ سامع وشايف الموقف،\n☆معلومة: \n رسول الله ﷺ كان يرى مَن خلفه زي ما بيشوف إللي قصاده بالضبط ،لأن هو كان له عين في قلبه يرى بهما ما لا يراه عامة الناس،\nزي ما شاف موسى عليه السلام لما كان بيصلي في قبره،\nوشاف الحاجات إللي اتكلمنا عليها في رحلة الإسراء والمعراج، \nفهو لما يكون مُعطي الصحابة ظهره بيبقى شايفهم كأنهم واقفين قصاده بالضبط، ودي من معجزاته ﷺ \nوالدليل على المعلومة دي قوله ﷺ: \"‎هَلْ تَرَوْنَ قِبْلَتِي هَا هُنَا ؟! \nوَاللَّهِ مَا يَخْفَى عَلَيَّ رُكُوعُكُمْ وَلَ خُشُوعُكُمْ ، وَإِنِّي لأَرَاكُمْ وَرَاءَ ظَهْرِي‎\"\nبعد الصلاة نادى رسول الله ﷺ على معاوية بن الحكم،\nفيقول معاوية : والله ما شفت معلم أحسن منه، قال لي من غير شتيمة ولا ضرب:\nيا معاوية الصلاة إللي احنا بنصليها دي مينفعش نتكلم فيها الكلام العادي،\nلكن بنسبح ونقرأ قرآن ونذكر الله.\n☆شوفوا بكل بساطة شرح له الموضوع ووجهوا، مقلوش مثلا  مش كنت تيجي تسألني الأول عشان أعلمك، \nولا عنّفه ولا كلمه بأسلوب وحش،\nأصل إيه الفايدة يعني من التقطيم والتعنيف \nالمطلوب إنه يعرف الصح وخلاص وهو ده إللي رسول الله ﷺ عمله، \nوخدوا بالكم إن ده رجل عاقل مش طفل،\nومع ذلك رسول الله ﷺ تعامل معاه بكل لطف وهو بيعلمه،\nفنقول إيه بقى للأباء والأمهات إللي طول النهار تقطم في عيالها كل ما يغلطوا وإللي أصلا ربنا رافع عنهم القلم لأنهم لسه صغيرين، ويعنفوهم ويتعاملوا معاهم بأسلوب سيء، \nوأنا مش قلت لك اعمل كذا إنت مبتفهمش إنت...إنت...\nطبعا غير الضرب والشتيمة\nربنا قال لنا : \n\"لَّقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا \"\nيعني اتبعوا رسول الله ﷺ في تصرفاته وكل حاجة بيعملها حتى طريقة تعليمه للناس\n عايزة بس أقول لكم على موقفين حصلوا مع رسول الله ﷺ  بما إننا بنتكلم على الضرب، وهي برده من حياة رسول الله ﷺ اليومية مع الصحابة،\n◇الموقف الاول:\nواحد من الصحابة كان اسمه أبو مسعود البدري كان عنده عبد وإنتم عارفين العبيد بيكونوا مستضعفين وتلاقوا سيده بيتعصب عليه من أقل حاجة وخصوصا لو معملش إللي طلبه منه زي ما هو عايز، \nزينا كده بالضبط لما بنعمل مع عيالنا، فرسول الله ﷺ عدّى عليه مرة وكان عمّال يضرب العبد ده بالسّوط، الكرباج يعني، \nخلينا نقرب المعنى للواقع بتاعنا،\nبالحزام أو بخرطوم البوتاجاز أو بشماعة الهدوم\nعايزاكم تتصوروا الموقف وهتلاقوه هو هو بالضبط\nشوفوا بقى رد فعل رسول الله ﷺ من الموقف ده كان إيه عشان تعرفوا الخطر الرهيب إللي احنا فيه\nكان عمال بيضربه بالسّوط وهو غضبان وخارج عن شعوره،\nرسول الله ﷺ لما شافه جاءه وقال له من وراء ظهره:\nاعلم أبا مسعود ، اعلم أبا مسعود، اعلم أبا مسعود، ثلاث مرات رسول الله ﷺ يكلمه وهو مش واخد باله من شدة الغضب إللي كان فيه،\nفقرب منه رسول الله ﷺ فانتبه أبو مسعود لرسول الله ووقع منه السّوط من هيبته لرسول اللهﷺ،\nفقال له رسول الله : \n\"اعلم أبا مسعود أن الله أقدرُ عليكَ منك على هذا الغلام\" يعني انت مستقوي على الغلام ده عشان ضعيف ...ربنا أقوى منك وقادر إنه يهلكك في لحظة،\nفخاف أبو مسعود وقال له: هو حر لوجه الله،\nفقال له رسول الله ﷺ  :\n \"أما لو لم تفعل للفَحَتك النار\"\nيعني لو مكنتش عملت كده كنت هتتعذب بالنار، \nفأقسم له أبو مسعود إنه مش هيضرب أي عبد له بعد كده أبدا\nممكن واحدة تقول ما العيال مستفزة ومقرفة ومبيسمعوش الكلام و...و...\nطيب هو إنتِ زوجك مش بيستفزك ويضايقك؟\n الناس إللي معاكِ في الشغل مش بيطلعوا عينك؟\nكل يوم مش بتقابلي ناس نفسك يختفوا من على وجه الأرض\nطيب اشمعنى مش بتضربيهم زي ما بتضربي عيالك؟\nالفرق إننا بنكون عارفين إن مفيش رد فعل من الاطفال هيحصل معانا فبنضرب العيال كده،\nلكن لو عارفين إن الضربة دي هتترد لنا في نفس اللحظة مش هنقدر نمد إيدنا عليهم،\nتخيلوا كده هل ممكن واحدة تخرج عن شعورها لو زوجها زعقلها أو اتخانق معاها وتديله بالقلم على وشه زي ما بتعمل مع ابنها ولا بنتها \n《طبعا الضرب على الوجه حرام مطلقا مفيهاش نقاش》\nفالموضوع مش هيّن خالص يا جماعة والله، كل ما حد يحس إن أعصابه هتفلت منه يفتكر حديث رسول الله ﷺ \nوأنا بقولكم العيال بتفتكر الذكريات السيئة والمؤلمة أكتر من الذكريات الحلوة، \nالألم النفسي مش بيتنسي والله مهما طال الزمن، ومهما الإنسان اعتذر ، وخصوصا لو من الأم إللي هي المفروض الملجأ الآمن ليهم ، فلما يكون الألم النفسي جاي من أمهم يروحوا فين بعد كده\nالأطفال مش بينسوا ...الأطفال عندهم مشاعر زينا وبيتألموا ...تخيلي كده لو حد بتحبيه ضربك بالقلم فجأة كده وكل ذنبك إنك مش فاهمة أو مش عايزة تعملي الحاجة دي، أو حتى غلطتي \nلو حطينا نفسنا مكانهم أكيد الوضع هيختلف\nوده هياخدنا للموقف الثاني مع رسول اللهﷺ لأن له صلة به،\nواحد من الصحابة جاء لرسول الله ﷺ وقعد قصاده قال له:\nيا رسول الله ! عندي مملوكين، عبيد يعني، بيكذبوا علي وبيخونوني ومش بيسمعوا كلامي، فأنا بشتمهم وبضربهم فإيه وضعي معاهم\nفقال له رسول الله ﷺ: \nربنا بيحسب كذبهم وعصيانهم وخيانتهم لك، وبيحسب ضربك وشتيمتك لهم ، فلو كان ضربك وشتمهم بقدر الغلط إللي عملوه معاك، خلاص يبقى مفيش حاجة لك ولا في حاجة عليك، \nولو كان عقابك أقل من غلطهم يبقى لسه لك عندهم حسنات،\nأما بقى لو عقابك أكثر من غلطهم فربنا هيقتص منك حقهم  يوم القيامة ويعطيه لهم\nفالرجل أخذ جنب وقعد يبكي بشدة، فقال له رسول الله ﷺ:\nهو إنت مقرأتش كلام الله :\n\"وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا ۖ وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا ۗ وَكَفَىٰ بِنَا حَاسِبِينَ \" \nفالرجل قال لرسول الله ﷺ: والله يا رسول الله أنا مش شايف حاجة أحسن لي ولهم غير إني أفارقهم، أُشهدك أنهم أحرار كلهم\nوالموقف ده رسالة للناس إللي بتقول إنها بتاخد حقها تالت ومتلّت، خدوا بالكم إنتم مش عارفين حقكم أد إيه بالضبط، فممكن تكونوا مفكرين إنكم أخذتم حقكم بس وانتم واخدين بزيادة، والزيادة دي ربنا هيأخذها منكم حسنات يوم القيامة،\nإن الله لا يظلم مثقال ذرة،\nعيالكم، أصحابكم ، أهلكم ، أزواجكم، كل إنسان قابلتوه،\nتحللوا من المظالم وسامحوا قبل ما ييجي يوم القيامة وميبقاش فيه غير الحسنات والسيئات\nإن شاء الله المرة الجاية هنكمل حياة رسول الله ﷺ مع الصحابة وهنتكلم عن قصة هاروت وماروت، وهنتكلم عن قصة رسول الله ﷺ مع زاهر ومع زيد بن ثابت،\nوممكن كمان لو في وقت نتكلم عن حكاية برصِيصَا العابد إللي رسول الله ﷺ حكاها للصحابة،\nفكلامنا الجزء إللي جاي وممكن إللي بعده إن شاء الله عن حياة رسول الله ﷺ مع الصحابة في المدينة،"}, {"n": 93, "l": "الجزء 67 | حياة رسول الله صلى الله عليه وسلم مع الصحابه الجزء الثاني | زيد ثابت وزاهر بن حرام | قصة هاروت وماروت والسحر", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السابعة_والستون\n#حياة_رسول_الله_مع_الصحابة_الجزء_الثاني\n#زيد_ثابت_وزاهر_بن_حرام\n#قصة_هاروت_وماروت_والسحر\nاتكلمنا المرة إللي فاتت عن حياة رسول الله ﷺ مع الصحابة في المدينة وشوفنا بعض مواقفه معاهم، \nهنكمل النهاردة إن شاء الله الكلام عن حياته ومواقفه مع الصحابة ونحكي كم موقف لرسول الله ﷺ،\nرسول الله ﷺ كان بيمازح أصحابه وكان متواضع جدا معاهم، وكان قريب منهم جدا زي ما ربنا أمره :\n\"وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ \"\nكان في صحابي اسمه زاهِر بن حرام يعيش في البادِية، من البدو يعني، وكان من الصحابة إللي حضروا غزوة بدر،\n فكان لما يأتي المدينة كان بيجيب معاه لرسول الله ﷺ هدية زي الثمار والنباتات والأدوية العشبية إللي مش بتكون موجودة إلا في البادِية وكان رسول الله ﷺ بيجهزه في سفره، كجزاء مقابل هديته،\nفكان رسول الله ﷺ يقول :\n\"إن زاهر باديَتنا ونحن حاضروه\"\nيعني هو بيفيدنا بالحاجات إللي بيجيبها من البادية ومش موجودة عندنا،\n واحنا بنجهزه بالحاجات إللي بيحتاج لها من البلد.\n◇عارفين زي مثلا لما حد ييجي من الأرياف زيارة لحد من المدينة ومعاه الجبنة الحدقة والفطير المشلتت، كده يعني\n وكان زاهر بيُضحك رسول الله ﷺ وبيحكي له مواقف فكاهية ،وكان رسول الله ﷺ بيحبه،\nوكان زاهر دمِيم ، يعني بلغة عصرنا شكله وحش...قبيح المنظر،\nفي يوم من الأيام كان زاهر في سوق المدينة بيبيع بعض أغراضه ورآه رسول الله ﷺ فجاءه من وراه وحضنه، وفي رواية إنه حط إيده على عينه،\nتخيلوا الموقف، واحد رافع إيده وماسك ملابس مثلا وبيعرض بضاعته في السوق وبعدين رسول الله ﷺ جاءه وحضنه من تحت إبطه وراح مغمي عينه وقعد رسول الله ﷺ ينادي:\n\"مَن يشتري العبْد...مَن يشتري العبْد\"\nمن باب المزاح، إن البائع بقى هو إللي بيتباع دلوقتي\nفزاهر قعد يقول: أرْسلني، يعني سيبني، وهو ميعرفش إن إللي حاضنه ده رسول الله ﷺ، \nفلما أخذ باله من إن الشخص إللي حاضنه ده هو رسول الله ﷺ قعد يلصق ظهره برسول الله ﷺ تبرّكا به ﷺ،\nوقال له زاهر:\nإذاً تجدُني كاسدًا يا رسول الله\nيعني مش هتلاقي حد يشتريني ولا يرغب فيّ أو ثمني رخيص، بسبب إنه شكله دميم،\nفقال له رسول الله ﷺ: لكنك عند الله لست بكاسد، لكنك عند الله ربِيح\nيعني إنت عند ربنا غالي مش رخيص، لأن الله لا يَنظر إلى شكل الناس ولا ملابسهم ولا لون بشرتهم،\nلكنه ينظر إلى قلوبهم\nتخيلوا لو الناس اهتمت بقلوبها زي ما بتهتم بإنها تلبس الملابس المكوية وتلبس الماركات العالمية وتلبس الألوان المتناسقة عشان يبقى شكلها حلو قصاد الناس،\nحالنا هيكون عامل إزاي\n☆زاهر كان حُر ورسول الله ﷺ لما كان بيمزح كان لا يقول إلا الصدق، فلما قال من يشتري العبد، كان يقصد إن زاهر عبد لله\nوهنا معلومة مهمة\nلا يجوز قول النكتة إللي فيها كذب، رسول الله ﷺ يقول:\n\"ويل للذي يُحدّث فيكذب ليضحك به القوم ويل له ثم ويل له\"\nوويل ده وادي في جهنم، يعني إللي هيكذب عشان يضحك الناس هيتعذب في وادي وَيْل\nويا سلام بقى لو اجتمع مع الكذب في النكتة الكلام الفاحش أو كلام فيه كفر...كارثة\nوبما إننا جبنا سيرة غزوة بدر فلازم نعرف إيه إللي حصل مع الصحابة إللي رسول الله ﷺ ردهم قبل ما يطلع في غزوة بدر\nلما رسول الله ﷺ قرر إنه يخرج لقافلة أبي سفيان، وقال للصحابة مين يخرج معي، جاءه كم واحد من الصحابة عايزين يخرجوا معاه، لكن رسول الله ﷺ رجعهم وقال لهم مش هينفع تخرجوا معايا، ليه\nلأن سنهم كان صغير، مينفعوش للقتال، ومن الصحابة دول كان عبد الله بن عمر بن الخطاب، وكان لسه مكملش اثنا عشرة سنة،\nوكمان رجّع زيد بن ثابت لأنه مكنش لسه أكمل ثلاثة عشرة سنة، يعني في ثانية إعدادي تقريبا، إللي هو بلغة عصرنا بنقول عليهم أطفال\nالأطفال دول كان همهم الجهاد في سبيل الله، كان همهم إنهم ينصروا رسول الله ﷺ، \nطبعا رسول الله ﷺ كان بيأخذ بأسباب النصر، ومن الأسباب دي إنه يعطي المسؤولية للي يقدر يتحملها،\nحاجة جميلة إن الأطفال دول عايزين يخرجوا للجهاد ووخداهم الحماسة بس احنا في دين الإسلام بنحسبها بالواقع وبالأسباب مش بالمشاعر\nفردهم رسول الله ﷺ لأنهم لسه غير مؤهلين للجهاد\nطيب خلاص بقى يقفوا ويجيلهم اكتئاب عشان معملوش إللي كان نفسهم يعملوه؟\nزيد بن ثابت إللي كان نفسه يخرج للجهاد مع رسول الله ﷺ ولقى باب الجهاد اتقفل قصاده يعمل إيه\nيعمل زي ذو القرنين، فاكرين\n\"ثم أتْبَع سبَباً\"\nالباب إللي يتقفل قصادنا خلاص نشوف غيره على طول\nباب الجهاد مقفول دلوقتي يبقى أشوف باب الإنفاق على الفقراء، \nمعنديش فلوس، يبقى أشوف باب الدعوة إلى الله بحسن خلقي ومعاملاتي الطيبة مع الناس، أشوف قدراتي إيه وأوظفها لخدمة الدين\nوده إللي عمله زيد بن ثابت رضي الله عنه \nزيد بن ثابت دوّر على باب تاني يخدم منه الإسلام، شاف إن عنده قدرات مختلفة مش موجودة عند حد، \nفهو حافظ سبعة عشرة سورة من القرآن، وبيعرف القراءة والكتابة ودي كانت حاجة نادرة جدا في الزمن ده،\nوفوق كده كان ذكي وعنده مَلَكة التعلم بسرعة، فذهب مع أمه لرسول الله ﷺ يعرضوا عليه طاقة زيد العلمية عشان رسول الله ﷺ يستعملها في خدمة الدين،\nفاختبره رسول الله ﷺ وشاف إن عنده فعلا موهبة، \nفأمره رسول الله ﷺ بأمر يُعتبر غريب\nأمره إنه يتعلم لغة اليهود، اللغة السريانية\nيعني يتعلم لغة أجنبية غير لغته العربية، وده لأنه ﷺ لا يأمن اليهود على كلامه،\nيعني اليهود ممكن يأخذوا كلام رسول الله ﷺ ويحوّروه، \nأو يطلب من اليهود قراءة حاجة بلُغتهم فينقصوا الكلام أو يزودوه، فاحنا محتاجين واحد نثق فيه يكتشف الحيل والألاعيب إللي أعداء الإسلام بيستخدموها للطعن في الإسلام\nزيد بن ثابت إللي يادوب عنده ثلاثة عشرة سنة دلوقتي تعلم اللغة السريانية كتابة وقراءة وأتقنها كأنه من أهلها بالضبط،\nعارفين زيد عمل كده في أد إيه\nأتقن لغة اليهود في سبعة عشرة يوما\nفي زمن مفهوش جامعات، مفهوش إنترنت ،مفهوش كورسات ولا دروس خصوصية، طفل يتقن لغة من اللغات الأجنبية لوحده في وقت قياسي\nلما الإنسان يُخلِص العمل لله، ويكون همه فعلا نصرة الإسلام ربنا بيفتح عليه من بركاته ويرزقه التوفيق،\nتخيلوا إن زيد بن ثابت بقى ترجمان الدولة الإسلامية، ترجمان رسول الله ﷺ، \nرسول الله ﷺ مقلش إن ده طفل صغير، أو خلينا نقول بلغتنا ده عيل، مينفعش إني أديله مهمة كبيرة زي دي،\n لأ...رسول الله ﷺ بيستغل كل الطاقات المتاحة لبناء أمة الإسلام، \nمفيش حاجة في الإسلام اسمها واحد ملوش أهمية، بس كل واحد يكتشف قدراته الحقيقية ويستغلها صح\n◇ممكن حد يقول ما احنا عيالنا لا يُعتمد عليهم وبقوا تافهين\nطيب وهو مين إللي خلاهم كده، مش احنا؟\nالطفل من وهو صغير لازم يتعود إنه يشيل مسؤولية على أد سنه شوية شوية وتحملوه هم الدين، \nمش يبقى طول بعرض وكل همه في الحياة وإللي شاغل تفكيره إنه يلعب بلاي ستيشن، ومفيش في دماغه غير ماتشات الكورة والألعاب \n\"أفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ\"\n☆ملحوظة مهمة أوي \nزيد بن ثابت لما تعلم لغة اليهود مكنش بيقعد يتكلم باللغة دي وسط المسلمين عشان يعرّفهم إنه بيعرف لغة تانية بقى وكده يعني\nتعلم اللغة مطلوب عشان هدف معين، غير كده مادام احنا وسط المسلمين العرب نتكلم بلغة القرآن ...اللغة العربية،\nلا رسول الله ﷺ ولا الصحابة كانوا بيتكلموا بأي لغة تانية 《بينهم》غير اللغة العربية، \nوبالنسبة للناس إللي بتقعد تقول أصل اللغات الأجنبية عايزة ممارسة والكلام ده،\nشوفوا الله يكرمكم زيد بن ثابت صاحب الثلاثة عشرة سنة إزاي أتقن السريانية في سبعة عشرة يوما قراءة وكتابة لدرجة إنه بقى زي أهلها من غير الممارسة إللي بتقولوا عليها دي، الموضوع محتاج إخلاص وصدق نية وربنا هو إللي بيرزق الفهم والتعليم\nفإيه الفايدة يعني لما أقعد أتكلم وسط ناس عرب بلغة أجنبية هم مش فاهمينها\nعمر بن الخطاب رضي الله عنه إللي الناس حافظة عنه قوله : اعتزل ما يؤذيك، وهو قول لا يصح عنه بالمناسبة قال :\n \"تعلموا العربية فإنها من دينكم\" وكان بيضرب الناس إذا تكلموا بكلام الأعاجم تخيلوا\nأمال لو شاف زماننا بقى هيعمل إيه\nويا سلام لو اتنين بيتكلموا بلغة أجنبية وهم عرب ومعاهم \nواحد مش فاهم الكلام، تخيلوا إن ده يدخل في حديث رسول الله ﷺ: \n\"إِذَا كُنْتُمْ ثَلَاثَةً فَلَا يَتَنَاجَى اثْنَانِ دُونَ صَاحِبِهِمَا\"\nبجد الموضوع بقى محزن جدا، وخصوصا لما يطلع من ناس المفروض إنهم ملتزمين\nعودوا نفسكم وعيالكم إنكم متتكلموش أي لغة تانية غير اللغة العربية إلا وقت الحاجة، غير كده اتكلموا عربي،\nاللغة العربية هي لغة القرآن، \nولو كان في لغة أحسن منها كان ربنا العليم الحكيم الخبير أنزل القرآن باللغة دي\nوخليكم فاكرين إن من صفات الجيل إللي هينصر الإسلام إنه جيل بيعظم اللغة العربية\nوبما إننا جبنا سيرة اليهود وتحويرهم للكلام، يبقى محتاجين نعرف قصة هاروت وماروت\nاحنا اتكلمنا قبل كده عن اليهود لما كانوا بيقولوا للأوس والخزرج إن في نبي هيخرج وصفته كذا وكذا وإنهم هيتبعوه ويقتلوا الأوس والخزرج قتل عاد وثمود،\nولما رسول الله ﷺ بُعث أنكروا الصفات إللي وصف بها رسول الله ﷺ في التوراة، وقالوا إن مش هو ده الرسول إللي مذكور عندنا في التوارة،\nفأنزل الله :\n\"وَلَمَّا جَاءَهُمْ رَسُولٌ مِنْ عِنْدِ اللَّهِ مُصَدِّقٌ لِمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ كِتَابَ اللَّهِ وَرَاءَ ظُهُورِهِمْ كَأَنَّهُمْ لا يَعْلَمُونَ \"\nفتركوا التوراة وتركوا العمل بها، فلما تركوا التوراة اتجهوا للكتب إللي الشياطين افترتها على سليمان عليه السلام،\n\"وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَىٰ مُلْكِ سُلَيْمَانَ\"\n فاكرين\nسريعا كده، قلنا إن سليمان عليه السلام لما مات الجن \nبدأت تبحث تحت عرشه عن الكتب التي كان يكتبها الكاتب  بتاعه وإللي يُقال إن كان اسمه آصف،\nوكان يكتب فيها كل شيء عن سليمان عليه السلام،\nعن الملك وعن الشريعة ..كل شيء،\nفلما الشياطين أخرجت الكتب بدأوا يكتبوا ما بين السطور كلمات السحر والكفر ودعاء غير الله،\nوخرجوا على الناس وقالوا لهم إن دي كتب سليمان وإنه كان مسخّر الجن والطير والريح بالسحر ده، \nوإن مفيش حاجة اسمها نبوة، وإن سليمان كان مسخرهم بالسحر،\nوالناس قرأت الكتب لقت فيها فعلا كلمات السحر والكفر بالله ودعاء غير الله، فانتشر بين الناس إن سليمان عليه السلام كان بيتعامل بالسحر وكان كافر بالله،\n\"وَمَا كَفَرَ سُلَيْمَانُ وَلَٰكِنَّ الشَّيَاطِينَ كَفَرُوا \"\nفربنا دافع عن سليمان عليه السلام وقال إنه لم يكفر ولم يكن ساحر، وإن الشياطين هم إللي كفروا بيعلموا الناس السحر، وبيعلموهم السحر إللي أُنزل على الملكين \n هاروت وماروت،\nوالملكين دول ربنا أنزلهم وجعلهم في صورة رجلين صالحين في مدينة بابل في العراق، مهمتهم إنهم يدافعوا عن سليمان عليه السلام،\n فكانوا بيعلموا الناس السحر ويوضحوا لهم إن في فرق بين السحر وبين النبوة،\nوإن السحر ده ممكن أي حد يتعلمه، أما النبوة فهي اختيار من الله عز وجل...معجزة ،مش حاجة مكتسبة، يعني مفيش واحد يعبد ربنا لزمن معين أو يتعلم علم معين فربنا يرزقه النبوة ويبقى نبي،\nلأ...النبوة والرسالة اصطفاء خااالص من عند ربنا\nفكان الملكين بيقولوا للناس إن السحر ممكن تتعلموه، لكن السحر ده كُفر بالله، وإن احنا فتنة واختبار وابتلاء من الله،\nفخد بالك هتضيع نفسك،\n\"وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ\"\nفلو الشخص أصرّ على تعلم السحر ده يعلموه\n\"فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ\"\n☆ممكن حد يسأل، وهو ربنا ينزل الفتن والاختبارات كده، يعني ربنا ينزل سحر على ملكين\nأه عادي، اختبار وفتنة زي باقي الفتن، شوفوا حديث رسول الله ﷺ بيقول إيه:\n\"إني أرى الفتن خلال بيوتكم كمواقع القَطر\"\nيعني الفتن كثيرة وبتنتشر بين الناس، فمفيش مانع من نزول الفتن والاختبارات من عند ربنا\nومتنسوش إن ربنا أنزل ملك قبل كده وابتلى به الاقرع والأبرص والأعمى، فاكرين لما اتكلمنا عنهم في قصص الأنبياء\n☆طبعا يا جماعة الكلام ده\n هو كلام جمهور المفسرين وتفسير الصحابة، وده أصح كلام اتقال في قصة هاروت وماروت وهو ظاهر القرآن ،ومفيش حديث صريح عن رسول الله ﷺ بيوضح قصتهم بالتفصيل، فالمفسرين شرحوا ظاهر الآية، \nوخدوا بالكم لأن هتلاقوا حاجات مكذوبة وموضوعة بتقول إن الملكين دول ربنا ركّب فيهم الشهوة ونزلوا إلى الأرض وزنيا بامرأة،\nفمسخ الله المرأة لكوكب الزهرة، والملكين بيتعذبوا في الدنيا و...و...،الكلام ده غير صحيح\nاستمر الاعتقاد عند اليهود بأن سليمان عليه السلام ساحر حتى عهد رسول الله ﷺ، ما عدا بعض العقلاء من اليهود،\nفلما جاء رسول الله ﷺ من نسل إسماعيل عليه السلام مش من منهم، اتبعوا الكلام إللي موجود في الكتب المفتراة على سليمان عليه السلام،\nفكانت الآية إللي ربنا دافع بها عن نبيه سليمان عليه السلام:\n\"وَمَا كَفَرَ سُلَيْمَانُ وَلَٰكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ\"\n☆فيه هنا سؤال: هل السحر فعلا موجود، يعني موضوع إن حد يعمل لحد سحر والكلام ده حقيقي\nالسحر ثابت وموجود وذكره الله في القرآن ، وكمان اتفق أكثر الأمم من العرب والفرس وبعض الروم والهند على إثباته، وهو من العلوم إللي ممكن فعلا أي حد يتعلمها،\nوبيستعين فيها بالجن، لكن الجن لا تستجيب للي عايز يتعلم السحر إلا إذا كفر بالله أولا،\nوطبعا يقدم القرابين للجن ويفعل الموبقات عشان الجن تساعده،\nوالسحر فيه إللي بيقتل وفيه إللي بيمرض وفيه إللي بيفرق بين الرجل وزوجته،\nيعني يشوف وجهها أو المرأة تشوف وجه زوجها على هيئة حمار أو شكل حاجة قبيحة جدا ومش هو الشخص إللي تزوجه، فيحصل النفور والتفرقة بينهم،\nطبعا يا جماعة كله بأمر الله، محدش يقدر يضر حد إلا بعلم ربنا وإذنه\nرسول الله ﷺ بيقول :\n\"واعلم أن الأمة لو اجتمعت على أن يضرّوك بشيء لن يضروك إلا بشيء قد كتبه الله عليك\"\nوربنا بيقول :\n\" وَمَا هُم بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ\"\nوفي قصة حصلت مع واحدة صحبتي، كانت هي ومامتها بينظفوا الشقة بتاعتهم فبقدر ربنا بيحركوا الكنبة وقعت منها إزازة صغيرة فيها ورق ملفوف،\nطبعا عرفوا إنها سحر على طول، واتصرفوا الحمد لله في الموضوع،\nالشاهد إن السحر ده مضرهمش بحاجة وفي نفس الوقت ربنا خلاهم يلاقوه ويتخلصوا منه،\nفي حين إن ناس تانية السحر يضرهم، فكله بأمر ربنا\nوالإنسان يتحصّن من السحر بالأذكار والتقرب إلى الله والمداومة على الطاعة وذكر الله،\nولما تفتحوا باب البيت أو تقفلوه تقولوا بسم الله، فلما تسمّوا على كل حاجة الشيطان مش بيكون له أي تأثير على الإنسان\n السؤال المهم بقى هل رسول الله ﷺ سُحر ولا لأ \nده إللي هنعرفه الجزء الجاي إن شاء الله \n☆"}, {"n": 94, "l": "الجزء 68 | هل سُحر رسول الله | هل الاذكار تحمي الانسان من السحر", "u": "", "t": "قصة رسول الله صلى الله عليه وسلم لما سُحر \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثامنة_والستون\n#هل_سُحر_رسول_الله\n#هل_الأذكار_تحمي_الإنسان_من_السحر\nكنا واقفين المرة إللي فاتت عند سؤال مهم وهو : هل سُحر رسول الله ﷺ \nنعم رسول الله ﷺ سُحر\nطيب إزاي يُسحر وهو رسول الله\nرسول الله ﷺ بشر، بيحصل له كل إللي بيحصل لأي بشر عادي من الأمراض والابتلاءات،\nفزي ما بيجيله مرض وهو رسول الله، وزي ما بتحصل له مشاكل وخلافات مع زوجاته وهو رسول الله،\nوزي ما بيحصل له ابتلاءات وهو رسول الله، برده سُحر وهو رسول الله \nلكن في نفس الوقت رسول الله ﷺ معصوم عصمة كاااملة في تبليغ شريعة الإسلام، \nيعني كل حاجة رسول الله ﷺ قالها لنا في الدين فهي صحيحة لأنه لا ينطق عن الهوى \nوالسحر أنواع،\nمنه السحر المؤثر على علاقة الرجل بزوجته، وهو ده السحر إللي أُصيب به رسول الله ﷺ، مش السحر إللي بيؤثر على العقل\nفكان يُخيّل إليه أنه أتى أهله يعني حصل علاقة زوجية بينه وبين واحدة من نسائه لكنه لم يفعل،\nوالسحر هنا مش سحر الرّبط، خدوا بالك في فرق بين سحر الربط، وبين سحر التخيّل إللي حصل مع رسول الله ﷺ \nوكون إن رسول الله ﷺ تعرض للسحر فده لا يُنقص من قَدره ﷺ نهائي،\nفالسحر مرض زي أي مرض ورسول الله ﷺ بشر يصيبه ما يصيب البشر من أمراض بصفة عامة،\nوموسى عليه السلام تعرض لسحر التخيل ده فاكرين\nلما السحرة ألقوا العِصي والحبال فخُيل لموسى عليه السلام من سحر السحرة إنها ثعابين بتتحرك،\n\"يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَى\"\nفإيه المشكلة هنا لما يحصل لرسول الله ﷺ سحر التخيل إنه فعل شيء وهو لم يفعله،\nده احنا كبشر من غير سحر ولا حاجة ساعات بنتخيل إننا عملنا الحاجة واحنا معملنهاش، \nيعني مثلا الواحد يتخيل إنه أطفأ نور الغرفة وبعدين يلاقيه مفتوح وهو مقفلهوش أصلا بس توهم إنه قفله،\nفمفيش إشكالية خالص،\nأنا بتكلم من جانب المنطق، أما من الجانب الشرعي فالحديث صحيح رواه البخاري ومسلم وغيرهم من أئمة الحديث\n☆طيب إيه قصة السحر ده حصل إزاي يعني\nغلام من اليهود كان يخدم رسول الله ﷺ، فاليهود قعدوا يتحايلوا عليه ويُغرُوه عشان يساعدهم في سحر رسول الله ﷺ لحد ما وافق،\nفأخذ شعرات من مشط رسول الله ﷺ، \nوأخذ شوية من أسنان مشط رسول الله ﷺ وأعطاها لليهود،\nراحوا لواحد منهم اسمه لَبِيد بن أعصم،\n《وفي رواية إن الغلام هو نفسه لبيد بن أعصم》\nوقيل إن لبيد بن اعصم ده من حلفاء اليهود من أهل المدينة أسلم نفاقا، يعني أظهر الإسلام وهو منافق، واتكلمنا عن المنافقين قبل كده\n فقال له رؤساء اليهود:\n انت أحسن واحد عندنا بيعرف في السحر، واحنا حاولنا نسحر محمد بس معرفناش،\nواحنا هنعطيك مكافأة أو هنعطيك أجر لو انت سحرت لنا محمد، فاتفقوا إنهم هيعطوه ثلاثة دنانير،\nأخذ الشعر وأسنان المشط وعمل عليهم سحر ودفن السحر ده في بئر لبني زُريق، بطن من بطون الأنصار زي فرع أو عيلة كده، زي ما بنقول دي أرض عائلة فلان\nفمرض رسول الله ﷺ وتغير مزاجه، ومكنش عارف عنده إيه، وكان يتخيل إنه يأتي نساؤه وهو لم يأتيهن،\nففي مرة وهو نائم جاءه ملكان، واحد قعد عند رأسه والثاني عند رجله، فقال الملك إللي عند رأسه للي عند رجله:\nهو ماله في إيه؟\nفقال له الملك إللي كان عند رجله: ده مطبُوب!\nمسحور يعني، فقال الملك: مين إللي سحره\nقال: لبيد بن أعصم، فقال : إزاي سحره؟ \n قال المَلك :\nبمشط ومشاطة! فقال الملك : وفين مكان السحر ده؟\nقال الملك إللي عند رجله ﷺ:\nفي قشر طلع نخلة موجود تحت حجر في أسفل بئر ذروان، فاستيقظ رسول الله ﷺ وقال لعائشة رضي الله عنها :\nربنا أخبرني بالمرض إللي عندي، فخرج رسول الله ﷺ مع مجموعة من أصحابه وراحوا البئر،\nلما شافوها لقوا ميتها عاملة زي نقيع الحناء، شوفوا لما بتحطوا الحنة في مية المية بتكون عاملة إزاي\nأهه مية البئر كانت عاملة كده، والنخل إللي حوالين البئر إللي كان بيشرب من البئر الْتوى سيفه يعني فروعه اتلوت كأنها رؤوس الشياطين،\nفنزل رجل في البئر وطلّع قشر النخلة من تحت الحجر، ولقوا فيها من شعر رسول الله ﷺ وأسنان مشطه، ولقوا تمثال من الشمع على هيئة رسول الله ﷺ وفيه إبر مغروزة في التمثال ده،\nولقوا وتر معقود فيه إحدى عشرة عقدة، الوتر إللي بيبقى في القوس ده عارفينه\nفي الوقت ده جاءه جبريل عليه السلام بالمعوِّذتين \n《الفلق والناس》وقال له :\nيا محمد! (قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ) وحل عقدة، يعني فك عقدة من العقد، (مِنْ شَرِّ مَا خَلَقَ) وحل العقدة إللي بعدها، لحد ما فك العقد كلها، \nوكان كل ما رسول الله ﷺ يشيل إبرة من التمثال يحس بألمها وبعدين يحس براحة،\nلحد ما شال الإبر كلها وخلاص رجع مُعافى مفيش فيه أي مشكلة،\nفالصحابة قالوا له : لو إنك تقتل اليهودي\nفقال لهم رسول الله ﷺ: أنا خلاص ربنا شفاني، وهو مستنيه عذاب شديد عند ربنا، ومش عايز أثير فتنة بين الناس\n☆توضيح لبعض نقط في قصة سحر رسول الله ﷺ \n◇قصة السحر دي بتفاصيلها صحيحة لم ينكرها إلا أهل البدع\n◇وقت القصة كان في السنة السابعة من الهجرة بعد صلح الحدُيبية، بس أنا قلتها دلوقتي لأننا كنا بنتكلم في السحر فعشان يبقى خلصنا باب السحر ده خالص\n◇العلماء اختلفوا هل المعوذتين سور مكية أم سور مدنية\nفي علماء قالوا إنها مكية وعلماء قالوا إنها مدنية، ولعل والله أعلم يعني وده رأيي الشخصي\nإن المعوذتين ممكن تكون نزلت في مكة، ولما حصلت قصة السحر جاء جبريل عليه السلام لرسول الله ﷺ بالمعوذتين في الموقف ده كأنها العلاج،\nيعني بيقول لرسول الله ﷺ ويقول لنا إن المعوذتين هم علاج فك السحر وعلاجه ، ويقول على الطريقة إللي نستخدم بها المعوذتين عشان نفك السحر، كل آية معاها فك عقدة\nبقول تاني : \nده رأيي الشخصي إللي استنتجته من الكلام، الله أعلم صح ولا غلط ،انا بأشارككم استنتاجي بس\nفلو حد سمع كلام من العلماء في النقطة دي ياريت يقول لي\n◇الناس إللي بتُنكر أو مش مستوعبة إزاي رسول الله ﷺ يُسحر، نقول لهم من باب العقل والمنطق ومن حكمة ربنا إن موقف سحر رسول الله ﷺ ده كان لازم يحصل\nمش احنا متفقين إن الإسلام دين شامل لكل جوانب الحياة وإنه دين يصلح لكل زمان ومكان، \nوإن رسول الله ﷺ هو القدوة إللي لازم نتبعه ونتبع طريقة تعامله مع الأحداث إللي بتحصل في حياتنا حتى المرض،\nطيب السحر من المرض ومنتشر \nنعمل إيه بقى لو مكنش الموقف ده حصل مع رسول الله ﷺ\n فبسبب الحادثة دي مع رسول الله ﷺ ربنا علّمنا إزاي نتعامل مع فك السحر\nزي ما علمنا إزاي نصبر على مصيبة فقدان الولد والزوجة والأصحاب عن طريق حياة رسول الله ﷺ\nطبعا ده بغض النظر إن الأحاديث إللي ذُكر فيها قصة سحر رسول الله ﷺ صحيحة فيجب إننا نصدق القصة سواء مقتنعين ولّا لأ\n☆وهنا بقى يطلع لنا سؤال قاتل\nإزاي رسول الله ﷺ يُسحر أصلا وهو سيد الخلق ولا يَفتر لسانه عن ذكر الله، واحنا عارفين إن الأذكار بتحمي الإنسان ، ورسول الله ﷺ حتى لما بينام قلبه مش بينام، وكمان هو أعبد الخلق لله\n◇أولا:\nالأذكار فعلا بتحمي الإنسان من الشر ومن الأمراض ومن الحسد والسحر،\nلكن الإنسان ممكن يُصاب بالأمراض مع إنه محافظ على الأذكار لسبب تاني زي تكفير السيئات أو رفع الدرجات،\nزي موقف رسول الله ﷺ، \nوممكن بسبب إن الشخص إللي بيقول الأذكار ده معندوش يقين بالله إنه فعلا هيحميه،\nأو قلبه مكنش حاضر وهو بيقول الأذكار، فنلاقيه تأثر بالمرض أو السحر أو الحسد\nوده طبعا لعامة الناس مش لرسول الله ﷺ ، لأن هو سيد الموقنين\n◇ثانيا:\nفي فرق بين الإصابة وبين الضرر\nيعني ممكن الإنسان يُصاب بالحسد أو السحر مثلا، لكن ميحصلهوش أي ضرر، أو إنه يتأثر بالإصابة تأثير بسيط مش التأثير الكامل،\nمثال عشان المعنى يوضح، رسول الله ﷺ قال : \n\"من قال حين يُمسي ثلاث مرات أعوذ بكلمات الله التامات من شر ما خلق لم يضره حُمّة تلك الليلة\"\nالحمة معناها لدغة كل ذي سم زي العقرب والأفعى، فتعلمها الصحابة وكانوا بيقولوها كل ليلة، وفي ليلة من الليالي لدغت أفعى جارية كانت قالت الذكر ده فمحستش بأي وجع ومحصلهاش حاجة، والطبيعي إن لدغة الحية مؤلمة،\nفهي أُصيبت لكن محصلهاش ضرر، فالشخص إللي بيحافظ على الأذكار بتاعة اليوم كله، أذكار الصباح والمساء وأذكار الدخول والخروج من البيت وأذكار النوم و...و...\nبيحصل معاه حاجة من ثلاثة:\n¤إما إن ربنا يحفظه من الإصابة والضرر، يمنعها يعني.\n¤أو إنه ممكن يحصل إصابة بس ميكونش لها تأثير إطلاقا،\nزي مثلا واحد خبطته عربية أو وقع من مكان عالي وقام سليم محصلهوش أي حاجة\n¤أو إن يحصل الإصابة ويحصل ضرر بسيط، والضرر هنا بيكون على حسب نقص كمال الذكر\nيعني مثلا واحد اتصاب بحسد أو سحر، في الطبيعي الحسد أو السحر ده كان هيقتله، لكن عشان هو بيقول الأذكار كان الضرر أقل\n\"لن يَضُرُّوكُمْ إِلَّا أَذًى\"\nيارب ماتكونوا تُهْتُم مني ويكون الموضوع واضح\n♡الكلام إللي أنا شرحته كله عن قصة سحر رسول الله ﷺ هو خلاصة الأحاديث الصحيحة وشرح العلماء،\nوبما إننا اتكلمنا عن اليهود، في قصة مشهورة عن رسول الله ﷺ مع جاره اليهودي إللي كان في مكة وكان بيضع القاذورات أمام بيته ﷺ، ورسول الله ﷺ مكنش بيعمل حاجة غير إنه بيشيل القمامة دي ويرميها بعيد،\nوبعدين في يوم ملقاش القمامة فعرف إن اليهودي مريض فراح زاره في بيته فاليهودي أسلم بسبب أخلاق رسول الله ﷺ، \nالقصة دي غير صحيحة إطلاقا \nالناس بتذكر القصة دي عشان يستشهدوا بتسامح رسول الله ﷺ، وده مش تسامح إطلاقا ده ضعف،\nورسول الله ﷺ مكنش ضعيف كده حاشاه\nالتسامح لما يكون حصل من واحد خطأ مرة ولا مرتين، لكن مش يبقى يهودي وبيؤذي النبي كده كل يوم ورسول الله ﷺ ميكونش له أي رد فعل\nده غير كده أصلا، رسول الله ﷺ لم يُخالط اليهود إلا في المدينة وهو قائد للمسلمين، وكان اليهود بيكيدوا للإسلام والمسلمين في السر، محدش يجرؤ أنه يعمل كده مع رسول الله ﷺ \nلكن في قصة ثانية لرسول الله ﷺ مع غلام يهودي تبين رحمة رسول الله ﷺ بالناس بصفة عامة،\nوهي إن كان في غلام من اليهود من عامة أهل المدينة بيشتغل زي خادم في البيوت، فذهب لرسول الله ﷺ عشان يخدمه، فكان بيساعده إنه يجيب له ماء الوضوء مثلا، عايز حاجة بيروح يجيبها له، وهكذا،\nطبعا الغلام شاف أخلاق رسول الله ﷺ، وانبهر إن إزاي سيد لا يضرب ولا يُعنّف خادمه، \nيعني يكفي إننا نتذكر في الموقف ده قصة زيد بن حارثة وإزاي إنه اختار يكون مع رسول الله ﷺ على إنه يرجع مع أبوه وعمه بسبب حسن معاملته له\nوطبعا الغلام كان بيحكي لأبوه إللي كان بيشوفه من معاملة رسول الله ﷺ وحسن أخلاقه،\nفي يوم من الأيام رسول الله ﷺ افتقد الغلام ده، يعني مش من عادته إنه يغيب عنه، فلما سأل عليه عرف إنه مريض،\nفراح رسول الله ﷺ للغلام يزوره في البيت فلقاه في سكرات الموت،\nفرسول الله ﷺ قال له: أسلِم!\nفالولد بقى ينظر إلى رسول الله ﷺ وينظر لأبوه، مش عارف يعمل إيه\nهل يسمع كلام رسول الله ﷺ إللي انبهر بأخلاقه وصدقه، ولا يكمل على دين أبوه إللي رباه وعاش معاه عمره ومش عايز يزعله،\nفقال له أبوه :أطع أبا القاسم\nفالغلام على طول قال:\nأشهد أن لا إله إلا الله وأن محمدا رسول الله، وخرجت روحه، فخرج رسول الله ﷺ من عنده وهو مبسوط وبيقول :\nالحمد لله الذي أنقذه بي من النار!\nاحنا محتاجين فعلا يكون ده همنا، إننا ننقذ الناس من النار،\nوأتذكر كلمة قرأتها زمان للشيخ الشعراوي لواحد من الناس إللي همهم قتل وتفجير غير المسلمين من أهل الذمة 《غير المحاربين》\nسأله وقال له: هو إيه هدف الشيطان في الدنيا؟\nفالرجل قال له : إنه يدخل الناس النار\nفالشيخ الشعراوي قال له: وإنت لما تقتل الناس إللي على غير ملة الإسلام هيروحوا فين؟\nقال له : هيروحوا النار، فقال له أهه انت كده بتساعد الشيطان في هدفه\nبعكس رسول الله ﷺ إللي كان همه إنه ينقذ الناس من النار زي ما شفنا، فاحنا لازم يكون ده همنا وهدفنا في الحياة،\nانقاذ الناس من النار زي ما رسول الله ﷺ كان بيعمل، مش قتلهم وخلاص، الإسلام لم يأتِ لقتل البشر، ولكن لإنقاذ البشر من النار \nوبالمناسبة في حديث برده مشهور لا يصح عن رسول الله ﷺ \nوهو إنه لما عدت عليه جنازة يهودي بكى وقال نفس تفلتت مني إلى النار\nلكن الحديث الصحيح عن موضوع جنازة اليهودي هو إن رسول الله ﷺ كان مرة جالس مع الصحابة ومرّت عليه جنازة يهودي ،\nفقام وقف احتراما للملائكة إللي كانت في الجنازة\n= مش احتراما لليهودي= ولأن الموت له فَزْعة، فالصحابة قالوا له إنها جنازة يهودي، فقال لهم : أوليست نفسا ؟ يعني هي مش نفس بشرية\n☆ملحوظة بمناسبة الغلام إللي نطق الشهادة في آخر لحظة \n ربنا يسّر للغلام ده إنه يقول كلمة التوحيد لأنه عالم إن قلبه يستحق هداية الإرشاد، يعني هو لو مكنش يستحقها ونفسه طيبة مكنش قالها، ومكنش ربنا يسّر له إنه يبعث له رسول الله ﷺ لحد بيته عشان ينقذه من النار،\nشوفوا ربنا بيقول إيه:\n\" إِن يَعْلَمِ اللَّهُ فِي قُلُوبِكُمْ خَيْرًا \" \nفلو الإنسان فعلا فعلا في قلبه خير وصادق هتلاقوا إن ربنا هداه حتى لو في آخر لحظة في حياته\nفعشان كده لازم نخلي دايما نيتنا خير، نخلي فعلا نيتنا وفي قلوبنا إننا يارب عايزينك وعايزين رضاك بس نفسنا بتغلبنا،\nوالشيطان بيضيعنا، واحنا فعلا عايزين نقرب،\nطول ماحنا نيتنا خير وعايزين الخير بصدق ،ربنا هييسره لنا حتى لو في آخر لحظة في العمر،\nولو سمعتم شرح اسم الله الهادي في سلسلة عرفت الله هتفهموا المعنى بصورة أوسع\nإن شاء الله هنتكلم الجزء الجاي عن أحداث السنة الثالثة من الهجرة، ونشوف الأحداث إللي حصلت فيها كانت إيه\n☆"}, {"n": 95, "l": "الجزء 69 | احداث السنه الثالثه من الهجره | غوزات قبل أحد | الفرق بين الحديث القدسي._النبوي_القران", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_التاسعة_والستون\n#أحداث_السنة_الثالثة_من_الهجرة\n#غزوات_قبل_أحد\n#الفرق_بين_الحديث_القدسي_النبوي_القرآن\nدخلت السنة الثالثة من الهجرة ومع نهاية شهر محرم وصل لرسول الله ﷺ أخبار إن ناس من بني ثعلبة ومحارب تجمعوا عشان يهجموا على المدينة،\nفجمع رسول الله ﷺ أربعمائة وخمسين مقاتل ما بين راكب على فرس وماشي على قدمه،\n☆وهنا يبان قدرة رسول الله ﷺ على جمع المعلومات وحكمته في سرعة خروجه عشان يقاتل أعدائه قبل ما يتجمعوا عليه،\nيعني زي ما بنقول خير وسيلة للدفاع هي الهجوم\nعدد المسلمين إللي رسول الله ﷺ جمعه ده كان أكبر عدد يتجمع للمسلمين حتى هذه اللحظة، فخرج بهم رسول الله ﷺ في الثاني عشر من ربيع الأول، \nواتجه نحو تجمُّع بني ثعلبة من بني غَطَفان ، واستخلف على المدينة عثمان بن عفان رضي الله عنه عشان يكون مكانه لحد ما يرجع، \nفي الطريق المسلمون أمسكوا برجل من بني ثعلبة اسمه جبّار وأدخلوه على رسول الله ﷺ، \nفدعاه رسول الله ﷺ للإسلام فأسلم الرجل\nومش بس كده ده بقى دليل لجيش المسلمين، يعني بيرشد جيش المسلمين إللي كانوا لسه أعدائه من شوية لمكان قومه بني ثعلبة إللي عايزين يهاجموا رسول الله ﷺ،\nقومه إللي عاش معاهم عمره، في لحظة كده بقى ولا كأنه يعرفهم،\nولاؤُه يعني حبه بقى لله ولرسوله، همه بقى مصلحة الإسلام حتى لو كان على حساب قومه إللي عاش معاهم سنين\nوصل الخبر لبني ثعلبة إن المسلمين في الطريق، فهربوا وتفرقوا في رؤوس الجبال \nوصل رسول الله ﷺ للمكان إللي كانوا متجمعين فيه، وكان في ماء في المكان ده اسمه ماء ذي أَمْر، فاتسمت الغزوة دي بغزوة ذي أمر، وبرده من أسمائها غزوة أنمار، \nعسكر رسول الله ﷺ في المكان، وذهب يقضي حاجته فنزل المطر، فملابسه ابتلت بماء المطر،\nفخلع ثوبه ووضعه على شجرة ينشف واضطجع تحت الشجرة، يعني زي ما بنقول فرد ظهره على الأرض مستني ثوبه ينشف،\nمين إللي شايف الموقف ده\nالناس إللي هربت من رسول الله ﷺ، فقالوا لسيدهم دَعْثور بن الحارث وكان رجل شجاع:\nمحمد لوحده دلوقتي محدش من أصحابه معاه، ودي فرصة مش هتتعوض\nفأخذ سيفه واتجه نحو رسول الله ﷺ إللي كان مضطجع تحت الشجرة، \nواتسحّب دعثور لحد ما وقف عند رأسه ﷺ والسيف في إيده وموجهه لوجه رسول الله ﷺ وهو بيقول له:\nمين يقدر يحميك مني يا محمد\n☆متخيلين الموقف\nكل واحد يحط نفسه مكان رسول الله ﷺ كده، نائم وفجأة واحد حاطط السيف على رأسه وبيقول له مين إللي يحميك مني، وهو فعلا لوحده ومش معاه سيفه وأي حركة هيعملها هيلاقي سيف الرجل في رقبته\nفقال له رسول الله ﷺ بكل هدوء وثقة ويقين:\n الله عز وجل\nأول ما قال رسول الله ﷺ الله، دفع جبريل عليه السلام دعثور في صدره فوقع السيف من يده، فأمسكه رسول الله ﷺ ووضع السيف على رأس دعثور وقال له:\nمين يقدر يحميك مني؟!\nفقال دعثور : مفيش حد \nوأنا أشهد أن لا إله إلا الله وأن محمدا رسول الله، والله ما هجمع الناس ضدك تاني أبدا\nفأعطاه رسول الله ﷺ سيفه ورجع الرجل لقومه،\nطبعا قومه المشركين كانوا شايفين الموقف كله، فلما وصل عندهم قالوا له: مالك، إيه إللي حصل\nفقال لهم: شوفت رجل طويل فدفع في صدري، ضربني في صدري يعني، فعرفت إنه مَلك، وشهدت إن محمد رسول الله، ووالله مش هجمع الناس ضده أبدا\nوقعد يدعوا قومه للإسلام، فأنزل الله قوله:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوا إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ \"\n☆ملحوظة\nفي قصة تانية مشابهة لقصة دعثور، هتحصل مع رسول الله ﷺ لرجل برده هيحاول قتله بنفس الطريقة، ولكن في غزوة تانية اسمها غزوة ذات الرقاع، هنتكلم عنها لما ييجي وقتها إن شاء الله\nقعد رسول الله ﷺ في المكان ده مدة قريبة من الشهر\nمحدش هجم على الجيش ولا حصلت أي مشاكل وسمعت العرب عن مجيء رسول الله ﷺ وجلوسه في المكان ده ومحدش قدر يقرب منه،\nوطبعا ده في صالح المسلمين، لأنه بيبيّن قوتهم، بعد ما كانوا مطاردين\nوحصلت غزوة تانية برده بعد ما رسول الله ﷺ رجع المدينة بحوالي شهر،\nوصل له الخبر إن بني سُليْم جمعت نفسها عشان يهجموا على المدينة، فجمع رسول الله ﷺ الصحابة وخرجوا لبني سليم وقبل ما يوصلوا بليلة،\nقابله رجل وقال له إن بني سليم لما عرفت إنك جاي لهم تحاربهم هربوا كلهم، \nفأخذ رسول الله ﷺ الرجل معاه وكمّل طريقه لحد ما وصل لمكان التجمع ده ولقاهم فروا فعلا، \nفلما تأكد من صدق الرجل تركه، ماهو مينفعش واحد منعرفوش ييجي يقول لنا معلومة نقوم مصدقينه كده على طول من غير ما نتأكد\nقعد رسول الله ﷺ في مكان التجمع ده وكان اسمه بحران فترة قبل ما يرجع للمدينة من أواخر شهر ربيع الآخر لحد شهر جمادى الأولى عشان يثبت للناس قوة الإسلام والمسلمين\n☆ممكن حد يسأل: هو إيه الفايدة يعني لما الناس تسمع بقوة المسلمين\nشوفوا،\nالهدف من غزوات رسول الله ﷺ بصفة عامة هو نشر دين الإسلام، \nوزي ما شفنا من قريش خلال أكثر من أربعة عشرة عام حربهم لدعوة الإسلام بكل طريقة وتعذيبهم للمسلمين المستضعفين،\nتخيلوا لما المسلمين يكونوا مستضعفين بيتعذبوا، الناس المستضعفة هتخاف تدخل في الإسلام وحتى لو دخلوا هيلاقوا الحكام ورؤساء القبائل إللي بيعذبوهم وإللي عايزين يرجعوهم عن دينهم،\nطيب إيه الحل\nنسيب الناس دي تُفتن، ولا نروح ندعوهم ونحميهم بقوة السيف ونطمنهم إن الدين إللي هتدخلوه ده فيه ناس هتقف معاكم وتحميكم\nفهو ده كان الهدف، إن رسول الله ﷺ يكسر شوكة المشركين \nعشان الناس تقدر تدخل في دين الله بدون خوف،\nوخصوصا إن المشركين في الوقت ده كانوا موجوعين وبيبذلوا كل جهدهم عشان ينتقموا من خسارتهم في غزوة بدر، فالغاية كانت نشر دعوة الإسلام وإنقاذ الناس من نار الآخرة\nوكان المشركون في الوقت ده متغاظين جدا من المسلمين، مش بس بسبب هزيمتهم في غزوة بدر،\nده كمان لأن طريق التجارة اتقطع عليهم، يعني هم كانوا بيعدوا على المدينة لما كانوا بيروحوا بتجارتهم للشام وده كان بالنسبة لهم طريق سهل،\nومكة حياتها كلها في التجارة، لكن بعد ما المسلمين سيطروا على المدينة وعلى طريق التجارة كان أهل مكة مضطرين إنهم يشوفوا طريق تاني يقدروا يسافروا منه للتجارة\nاجتمع أهل مكة بقيادة صفوان بن أمية إللي كان قائد رحلة التجارة السنة دي،\nقال لهم:\nمحمد وأصحابه قطعوا علينا طريقنا، حتى طريق الساحل مش هنقدر نمشي منه، لأن الناس هناك عملوا معاه معاهدة صلح،\nولو قعدنا هنا من غير تجارة رؤوس أموالنا هتخلص، واحنا حياتنا في مكة أساسها التجارة، نعمل إيه\nفقال الأسود بن عبد المطلب لصفوان ولمن معه من المشركين: \nأنا هقول لك، إنت تسيبك من طريق الساحل وخذ طريق العراق أحسن\n☆طريق العراق طويل جدا وحتى قريش متعرفش الطريق ده ومحتاجين فيه دليل ماهر جدا عشان يعرفوا يمشوا في الطريق ده ويوصلوا إلى الشام،\nودليل يعني الرجل إللي بيعرف طرق الصحراء\nالمهم قريش وافقت على الرأي ده لأن مفيش غيره أصلا،\nواختاروا دليل اسمه فُرات بن حيّان من بني بكر بن وائل،\nخرجت عير قريش، القافلة يعني ومشيوا في الطريق ده مع دليلهم فرات بن حيان،\nرسول الله ﷺ كان عامل حسابه، وعارف قريش بتفكر إزاي، ماهو عاش معاهم سنين طويلة\nفكان حاطط زي ما بنقول دوريات مراقبة ، أو مخابرات كده\nالمخابرات دي عرفوا بالقافلة، فبسرعة عرّفوا رسول الله ﷺ بالقافلة، وعلى طول رسول الله ﷺ جهز سرية من مائة من الصحابة بقيادة زيد بن حارثة إللي كان ساعتها لسه اسمه زيد بن محمد،\nوانطلقوا بسرعة لقطع الطريق على القافلة وكان ده في جمادى الآخرة،\nفلما هجمت السرية على القافلة هرب صفوان بن أمية وترك وراءه القافلة والدليل فرات بن حيان،\nوأخذ المسلمون القافلة وكانت تُقدر بمائة ألف دينار، وأخذوا فُرات بن حيان أسير،\nفكانت غنيمة كبيرة جدا للمسلمين، والطامة الكبرى إللي حصلت للمشركين إن فرات بن حيان أسلم، يعني خسروا القافلة والدليل الماهر \nفكانت دي ضربة قاسية جدا لقريش، وموقفهم بقى صعب جدا\nتخيلوا عندهم أزمة اقتصادية بسبب إن تجارتهم وقفت،\nوأزمة سياسية بسبب هزائمهم إللي ورا بعض قصاد المسلمين، فهيبتهم ضاعت وسط العرب، \nده غير الأزمة الاجتماعية، سبعين واحد من سادات مكة قُتلوا في بدر، فأهلهم عايزين يأخذوا بثأرهم من المسلمين، \nيعني مكة دلوقتي كأنها على فوهة بركان هينفجر في أي لحظة\nهيقعدوا يفكروا ويخططوا عشان يشوفوا هينتقموا من المسلمين إزاي،\nفاحنا هنسيبهم يخططوا ونروح لرسول الله ﷺ في المدينة ونشوف أحوال المسلمين الداخلية كانت إيه،\nوبعدين هنبقى نرجع نشوف المشركين وصلوا بتخطيطهم لحد فين \nرسول الله ﷺ كان يمارس حياته الطبيعية مع المسلمين،\nيخرج للصلوات الخمس، كان المؤذن لكل صلاة بلال بن رباح،\nوساعات كان المؤذن عبد الله بن أم مكتوم،\nكان رسول الله ﷺ بيقعد مع الصحابة ويتكلم معاهم، يرد على إللي جاي يسأله سؤال،\nزي ما أتاه رجل من الأعراب كبير في السن وفي رواية سقط حاجباه على عينه من كبر سنه وكان متسند على عصا يسأله:\nلو في واحد عمل كل الذنوب، مسبش أي معصية إلا وعملها سواء معصية صغيرة أو كبيرة، هل له من توبة\nفقال له رسول الله ﷺ:\nهل أسلمت؟\nفقال له الأعرابي: أما أنا فأشهد أن لا إله إلا الله وأن محمدا رسول الله\nفقال له رسول الله ﷺ: نعم، تعمل الخيرات وتترك السيئات فيجعلهن الله لك خيرات كلهن،\nيعني بعد ما أسلمت، تسيب السيئات وتعمل الخيرات، وربنا هيبدل لك كل سيئاتك إللي فاتت حسنات،\nفقال له الرجل:\nوغدراتي وفجراتي يا رسول الله \nقال له رسول الله ﷺ: نعم\nفالرجل قعد يقول الله أكبر ..الله أكبر...الله أكبر، وفضل يكررها لحد ما مشي واختفى عن أنظار رسول الله ﷺ والصحابة\n☆ وهنا رسالة لكل واحد أسرف على نفسه بالمعاصي، وعمل زي الأعرابي، مسبش صغيرة ولا كبيرة إلا وعملها،\nزي ما الإسلام يمسح إللي قبله، فالتوبة بتمسح إللي قبلها،\nالموضوع سهل وبسيط :\nتوبة + عمل خيرات +ترك السيئات= يبدل الله السيئات إلى حسنات\n\"إِلَّا مَن تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَٰئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ ۗ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا\"\nلسه في فرصة، ربنا بيقبل توبة العبد ما لم يُغرغر، يعني بيقبل التوبة مادام الروح موصلتش للحلقوم، يعني موصلتش لمكان الغرغرة في الفم،\nوبما إننا تكلمنا عن قبول الله لتوبة من تاب إليه، يبقى لازم نذكر الحديث القدسي الرائع المريح جدا إللي يأسر قلب أي حد يقرأه ويهيج مشاعر التوبة والرجاء والحنين لله عز وجل،\nقال الله تعالى في الحديث القدسي:\nيا ابن آدم   إنك   ما   دعوتني   ورجوتني   ، غفرت   لك على   ما كان  منك  ولا أُبالي،\nيا ابن آدم   لو  بلغت   ذنوبك   عنان  السماء   ثم استغفرتني   غفرت لك   ولا أُبالي،\nيا ابن آدم   لو   أتيتني  بقراب الأرض   خطايا   ثم   لقيتني   لا تشرك   بي    شيئا   لأتيتك    بقرابها   مغفرة.\nمجرد ما الإنسان يدعو ربنا ويرجوه؛ ربنا يغفر له، مجرد ما الإنسان يستغفر ربنا من قلبه ربنا يغفر له حتى لو كمية ذنوبه وصلت لحد أعلى السماء،\nلو الإنسان ملأ الأرض خطايا وتاب وأناب، ربنا هيقابله بملئ الأرض عفو ومغفرة\nربنا رحيم بس احنا ناخد خطوة ونقرب، وربنا قال في حديث قدسي تاني:\n\"من تقرب إليّ شبرا تقربت إليه ذراعا\"\nربنا بيقرب مننا بس لما احنا إللي ناخد الخطوة الأولى ونقرب منه\n◇طبعا السؤال إللي يطرح نفسه هنا : إيه هو معنى الحديث القدسي، وإيه الفرق بينه وبين الحديث النبوي العادي، وبين القرآن\n◇الحديث القدسي والحديث النبوي والقرآن بيشتركوا في إنهم الثلاثة وحي من عند الله عن طريق جبريل عليه السلام، أو عن طريق الرؤيا، أو عن طريق إنه يُقذف في روعه ﷺ، يعني حاجة تيجي في نفسه.\n♡الحديث القدسي : \nهو كلام الله ينقله رسول الله ﷺ من غير القرآن، وملوش حكم القرآن،\nيعني مينفعش نقرأ الحديث القدسي في الصلاة\nالحديث القدسي مش معجزة زي القرآن، \nنقدر نتعبد بالقرآن لكن لا نتعبد بالحديث القدسي، واللفظ والمعنى من عند الله \nزي المثال إللي قلناه من شوية، وزي حديث :\nقال رسول الله ﷺ فيما يحكيه عن رب العزة :\n\"يا عبادي! إني حرمت الظلم على نفسي وجعلته بينكم محرما، فلا تظالموا\"\nفهنا الكلام والمعنى من عند الله عز وجل\n♡الحديث النبوي :\nهو تشريع من عند الله، لكن اللفظ يعني الكلام، رسول الله ﷺ هو إللي قاله، يعني ننسبه إلى رسول الله ﷺ، \nيعني المعنى = إللي هو التشريع = من عند الله، واللفظ رسول الله ﷺ هو إللي بيقوله، أو بيشرحه.\nزي مثلا :\nقال رسول الله ﷺ:\n\"إنما الأعمال بالنيات، وإنما لك امرئ ما نوى\"\n♡القرآن الكريم:\nكلام الله لفظا ومعنى، وهو معجزة من المعجزات، لا تقوم الصلاة إلا بتلاوته بعكس الحديث القدسي\nنرجع لرسول الله ﷺ في المدينة،\nمن الناس إللي أتوا لرسول الله ﷺ عشان يسألوه، رجل يحكي عنه عمر بن الخطاب رضي الله عنه، يقول:\nمرة واحنا قاعدين مع رسول الله ﷺ فجأة طلع علينا رجل شديد بياض الثياب، يعني هدومه بيضة جدا، \nوشعره أسود جدا، مش باين عليه أثر السفر ومحدش فينا يعرفه\n☆عمر بن الخطاب مستغرب ليه؟\n لأن ده رجل غريب محدش يعرفه من الصحابة، يبقى المفروض إنه جاي مسافر، \nطيب وإللي جاي مسافر ده في صحراء وسط التراب والعفرة، إزاي ملابسه تبقى شديدة البياض، \nوشعره شديد السواد، فلو قلنا إنه ممكن كان على سفر وراح استحم عند واحد من الصحابة ممكن، لكن ده محدش من إللي قاعدين يعرفه، يبقى إيه ده\nيكمل عمر بن الخطاب حكاية الموقف:\nجلس الرجل قصاد رسول الله ﷺ، وأسند ركبتيه إلى ركبتي رسول الله ﷺ ووضع يده على فخذه وبدأ يسأل رسول الله ﷺ:\nعرفني إيه هو الإسلام، فقال له رسول الله ﷺ:\nالإسلام أن تشهد أن لا إله إلا الله وأن محمدا رسول الله، \nوتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان ، وتحج البيت إن استطعت إليه سبيلا!\nفقال له الرجل : صدقت \nفاستغرب عمر بن الخطاب والصحابة إللي كانوا معاه، يسأله ويصدقه\nفقال الرجل لرسول الله ﷺ:\nطيب أخبرني عن الإيمان.\nفقال له رسول الله ﷺ: \nأن تؤمن بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره!\nقال الرجل : صدقت\n ،قال : فأخبرني عن الإحسان.\nقال له رسول الله ﷺ: \nأن تعبد الله كأنك تراه، فإن لم تكن تراه فهو يراك\nقال فأخبرني عن الساعة، قال له رسول الله ﷺ:\nأنا زيي زيك معرفش عنها حاجة!\nفقال له الرجل:\nطيب قل لي إيه علاماتها؟\nفقال له رسول الله ﷺ:\nأن تلد الأمة ربتها ، يعني هيكثر الإماء بسبب كثرة الجهاد، فيتسرّى بها المسلمون، \nيعني المسلمين يعاشروا الإماء زي معاشرة الزوجات، فتلد الإماء نساء أحرار، فتكون البنت هي سيدة أمها،\nوأن ترى الحُفاة العراة العالة رعاء الشاء يتطاولون في البنيان،\nيعني العرب إللي كانوا مش لاقيين ياكلوا وبيرعوا الغنم وعايشين في الخيام هيبنوا بنايات عالية!\nفقام الرجل من عند رسول الله ﷺ ومشي، وبعد شوية قال  رسول الله ﷺ لعمر بن الخطاب،\nعارف مين السائل؟\nفقال عمر بن الخطاب رضي الله عنه:\nالله ورسوله أعلم\nفقال له رسول الله ﷺ: هذا جبريل جاء يعلمكم دينكم\nوبما إن الكلام وصل بنا لعمر بن الخطاب يبقى لازم نحكي عن ......\nهنعرف المرة الجاية إن شاء الله"}, {"n": 96, "l": "الجزء 70 | سبب تعدد زوجات رسول الله | مقدمات غزوة احد", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السبعون\n#سبب_تعدد_زوجات_رسول_الله\n#مقدمات_غزوة_أحد\nكنا واقفين المرة إللي فاتت عند القصة إللي حصلت مع عمر بن الخطاب رضي الله عنه،\nبعد غزوة بدر وانتصار المسلمين فيها، كان في مصابين من المسلمين في غزوة بدر منهم عُبيدة بن الحارث بن عبد المطلب إللي أصيب في المبارزة يوم بدر،\nومات بعدها في أواخر شهر رمضان بسبب جراحه، من الناس إللي أُصيبت يوم بدر صحابي اسمه خُنَيْس بن حُذافة السهمي، وكان من السابقين إلى الإسلام هو وزوجته، وكان من الذين هاجروا إلى الحبشة في الهجرة الثانية،\nوهاجر إلى المدينة وحضر غزوة بدر ومات بعد غزوة بدر بسبب جراحه وترك زوجته إللي كان عمرها في الوقت ده حوالي واحد وعشرين عام،\nفأصبحت زوجته أرملة في سن صغير ومكنش عندها أولاد، زوجته دي كان اسمها حفصة بنت عمر بن الخطاب \nلما مات زوجها أراد أبوها عمر بن الخطاب رضي الله عنه إنه يبحث لها عن زوج صالح،\nوبطبيعة الحال الأب دايما بيكون عايز لبنته أحسن زوج، فبدأ يشوف مين من أصحابه ممكن يكون زوج لبنته،\nأول واحد فكر فيه عثمان بن عفان رضي الله عنه، واحد من العشرة المبشرين بالجنة،\nرسول الله ﷺ شهد له بالجنة، وهو إللي اشترى بئر رومة مقابل الجنة، ورسول الله ﷺ زوجه من ابنته،\nورسول الله ﷺ مش هيزوج بنته لأي حد \nوهو دلوقتي معندوش زوجة لأن رقية بنت رسول الله ﷺ ماتت، فهل في أحس من كده زوج\nراح عمر بن الخطاب لعثمان بن عفان وقال له :\nلو عايز ممكن أزوجك حفصة بنت عمر\nفقال له عثمان بن عفان رضي الله عنه: طيب خليني أفكر وأرد عليك\nوبعد كم يوم جاءه عثمان وقال له:\n أنا مش عايز أتزوج في الوقت الحالي!\nففكر عمر بن الخطاب مين تاني ينفع يكون زوج لحفصة\nبس مفيش غيره برده واحد من العشرة المبشرين بالجنة،\nصاحب رسول الله ﷺ، \nأحب الناس إلى رسول الله ﷺ ورسول الله  متزوج من بنته، وطبعا رسول الله ﷺ مش هيتزوج أي حد كده \nيعني من الآخر رجل مفيش عليه أي غبار\n☆يعني إيه عشرة مبشرين بالجنة\nيعني عشرة من الصحابة بشرهم رسول الله ﷺ أنهم من أهل الجنة، واتسموا عشرة مبشرين بالجنة مع إن رسول الله ﷺ بشّر ناس كثير غيرهم رجال ونساء بالجنة؛\nلأن العشرة ذُكروا في حديث واحد في نفس الوقت وراء بعض، وهم أفضل أمة محمد ﷺ من بعده وهم: \n♡أبو بكر الصديق ♡عمر بن الخطاب ♡عثمان بن عفان ♡\nعلي بن أبي طالب ♡طلحة بن عبيد الله♡الزبير بن العوام ♡عبد الرحمن بن عوف♡سعد بن أبي وقاص♡سعيد بن زيد بن عمرو بن نفيل♡أبو عبيدة عامر بن الجراح♡\nذهب عمر بن الخطاب لأبي بكر الصديق رضي الله عنه وقال له:\nلو عايز، ممكن أزوجك حفصة بنت عمر\nفأبو بكر الصديق مردش عليه خالص، سكت\nفعمر بن الخطاب زعل وغضب من أبي بكر الصديق رضي الله عنه إنه مردش عليه،\nيعني عثمان رد ورفض وخلاص، لكن أبو بكر مقلهوش حاجة خالص، وغضب عمر من أبي بكر لأن كان في بينهم مودة وعلاقة قوية، غير أي حد تاني\n☆على فكرة عثمان  بن عفان في الوقت ده كان عمره فوق الخمسين سنة، وأبو بكر الصديق كان برده فوق الخمسين حوالي أربعة وخمسين سنة،\nوعمر بن الخطاب كان أصغر من عثمان بن عفان ومن أبي بكر، يعني عمر بن الخطاب بلغة عصرنا كان بيعرض بنته بنت العشرين على رجلين أكبر من أبوها في العمر\nيعني هي مش بايرة ولا حاجة\nوكرامتها متهانتش لما أبوها راح يعرضها على الناس الصالحين، ولا نقص من قدرها في وسط المجتمع حاجة\nولو كان الموضوع فيه مشكلة كان زمان الناس عابت على عمر بن الخطاب وإنت إزاي تعرض بنتك للزواج، \nهي سلعة وإزاي إنت أصلا إللي تختار لها، هي إيه ملهاش رأي وملهاش عقل تختار بنفسها، والحاجات العجيبة إللي بنسمعها في زماننا دلوقتي\nيجوز يا جماعة للأب إنه يعرض بنته على \n《الرجل الصالح》 واخدين بالكم الرجل الصالح هه\nومش من صفات الرجل الصالح إنه يعاير زوجته إن أبوها عرضها عليه عشان يتزوجها\nأما بالنسبة للفرق في السن فده دليل إن الموضوع كان عادي جدا في الزمن ده، يعني كان عندهم طبيعي إن المرأة تتزوج إللي أكبر منها بأكثر من عشرين وثلاثين سنة\nنرجع لعمر بن الخطاب رضي الله عنه بيقول: عدى كم يوم ولقيت رسول الله ﷺ جاي يخطب حفصة، فزوجتها له\nيعني هو كان بيدور على زوج صالح لبنته، ربنا بعث له مش زوج صالح بس، لأ ده بعث له سيد الأولين والآخرين ليكون زوج بنته\nبعدها قابله أبو بكر الصديق رضي الله عنه وقال له:\nإنت زعلت مني عشان انا مردتش عليك لما عرضت عليّ حفصة صح؟\nفقال له عمر : نعم\nفقال له أبو بكر الصديق: أنا مقدرتش أقول لك حاجة لأني عرفت إن رسول الله ﷺ ذكرها، يعني كان ناوي يخطبها،\nوأنا مستحيل أفشي سر رسول الله ﷺ، \nولو كان تركها ولم يخطبها كنت هتزوجها\nفأبو بكر وضح لعمر بن الخطاب رضي الله عنه السبب إللي خلاه ميتكلمش، وهنا نستفيد نقطة مهمة\nوهي نقطة الإعتذار\nأنا حسيت مثلا إن حد زعل مني في شيء، عادي جدا إني أوضح له وجهة نظري وأصالحه، مع إن أنا مش غلطان أصلا ومعايا عذري،\nزي موقف أبو بكر رضي الله عنه، يعني رسول الله ﷺ تكلم مع أبو بكر إنه ناوي يخطب حفصة وده سر لأن المجالس بالأمانة،\nهنفترض إن أبا بكر كان قال لعمر ده رسول الله ﷺ قال إنه هيخطب حفصة وبعدين يحصل حاجة ورسول الله ﷺ ميخطبهاش، فأكيد عمر هيزعل وينكسر قلبه،\nفكان الموضوع كله في مصلحة عمر بن الخطاب رضي الله عنه ومع ذلك زعل وغضب على أبي بكر، لأنه مكنش عارف جوانب الموضوع كلها،\nوبتحصل معانا مواقف زي كده وأوقات كتير مش بناخد بالنا منها، يبقى موقف ظاهر لنا مؤلم ونكتشف بعدين ده إذا اكتشفنا يعني \nإن الشخص ده كان عايز مصلحتنا وخايف علينا، بس احنا إللي مكناش فاهمين قصده ومش شايفين الصورة كاملة فيحصل شقاق على شقاق، بسبب الفهم الخطأ وعدم وجود حوار بين الطرفين\nوده عكس إللي حصل بين أبو بكر وعمر رضي الله عنهما، \nاتكلموا مع بعض ووضح أبو بكر الصديق وجهة نظره وانتهى الموضوع واستمر الود بينهما\nوبما إننا اتكلمنا على بنت عمر بن الخطاب، فانتم أكيد عارفين القصة المشهورة إللي بتُروى عن عمر بن الخطاب إنه كان له بنت في الجاهلية وكان بيكرهها فأخذها وحفر لها حفرة في الأرض وكان التراب بيصيب لحيته وهو بيحفر فكانت بتنفض التراب عنه وبعدين دفنها في الحفرة و هي حية\nأحب أبشركم زي مانا استبشرت بالضبط إن القصة دي غير صحيحة عن عمر بن الخطاب رضي الله عنه \n◇أولا :\nمفيش أي رواية في كتب السنة والحديث أو كتب التاريخ والآثار بتقول إن عمر بن الخطاب دفن بنت من بناته.\n◇ثانيا:\nلو كان وأد البنات منتشر في بني عَديّ قوم عمر بن الخطاب، إزاي حفصة بنت عمر أكبر أولاده إللي اتولدت في الجاهلية وقبل البعثة بخمس سنوات لسه عايشة لحد دلوقتي ومقتلهاش\nفوأد البنات مكنش منتشر عند كل الناس في الجاهلية، كان عند بعض الناس، وبني عدي مكنش منتشر عندهم وأد البنات وإلا فإزاي فاطمة بنت الخطاب أخت عمر فضلت عايشة وكمان حفصة \n◇ثالثا:\nعمر بن الخطاب يقول : جاء رجل لرسول الله ﷺ اسمه قيس بن عاصم وقال له إنه وأَد ثمان بنات في الجاهلية، يعني دفن ثمان بنات وهن أحياء، فقال له رسول الله ﷺ: \nأعتق رقبة لكل واحدة منهن، يعني المفروض هيعتق ثمان عبيد عن البنات الثمانية،\nفقال له قيس بن عاصم : أنا عندي إبل، فقال له رسول الله ﷺ: اذبح عن كل واحدة منهن بُدْنة، يعني كل واحدة يذبح عنها جمل،\nفدي كانت كفارة من قتل ابنته في الجاهلية،\nفعمر بن الخطاب رضي الله عنه بيحكي عن واحد وأد بناته، \nفلو كان عمر وأَد بنته كان عمل الكفارة دي وهو أصلا راوي الحديث\nوكده يبقى رسول الله ﷺ معاه ثلاث زوجات:\nسودة بنت زَمْعة، وعائشة بنت أبي بكر الصديق وحفصة بنت عمر بن الخطاب رضي الله عنهم أجمعين،\nأما عثمان بن عفان رضي الله عنه فتزوج ببنت رسول الله ﷺ أم كلثوم بعد موت أختها رقية بعد غزوة بدر، \nوسُمّي عثمان رضي الله عنه بذي النّورَيْن لأنه تزوج ابنتين من بنات رسول الله ﷺ،\nوبعد زواج رسول الله ﷺ من حفصة بوقت قليل وفي شهر رمضان من السنة الثالثة من الهجرة تزوج رسول الله ﷺ من زينب بنت خزيمة، بعد موت زوجها عُبيدة بن الحارث الذي أصيب في بدر واتكلمنا عنه في البداية\nتزوجها رسول الله ﷺ مواساة لها بعد موت زوجها، وكانت امرأة تقية تساعد المحتاجين لدرجة إن كان لقبها أم المساكين،\nوكانت في حدود الثلاثين من عمرها، ولما خطبها رسول الله ﷺ جعلت أمرها لرسول الله، يعني قالت له إنها هتعمل إللي هو هيقول عليه فتزوجها ﷺ،\nكده رسول الله ﷺ بقى عنده أربع زوجات، ومحتاجين نجاوب على سؤال مهم في موضوع تعدد زوجات رسول الله ﷺ \n☆لماذا تزوج رسول الله ﷺ أكثر من زوجة، حتى إنه هيتزوج أكثر من أربع زوجات زي ما هنشوف\n◇أولا :\n تعدد الزوجات بصفة عامة كان مشهور أيام الجاهلية وفي الأمم السابقة، وشفنا إن سليمان عليه السلام كان عنده ألف امرأة، ويُقال مائة، فكان عادي عندهم، حتى النساء كانوا متقبلين الفكرة، \nأيوة طبعا كان بيكون في غيرة لأن دي طبيعة في البشر، حتى بين النساء أيام الجاهلية، لكن الفكرة نفسها بالنسبة لهم كانت قائمة، يعني حتى في واحد جاء لرسول الله ﷺ يُسلم وهو متزوج من عشر نساء\nفرسول الله ﷺ قال له اختار أربعة منهن فقط، وواحد تاني كان متزوج من ثمانية زوجات، رسول الله ﷺ قال له برده يختار أربعة بس، فالموضوع مكنش فيه مشكلة كبيرة زي الواقع بتاعنا دلوقتي\nوطبعا محدش يتكلم عن العدل بين الزوجات ساعتها؛ لأن المرأة أصلا قبل الإسلام مكنش لها رأي ولا مكانة\nفلما جاء الإسلام وضع حدود وشروط للتعدد\nومن حكمة ربنا في إباحة إن الرجل يتزوج أكثر من واحدة لأن عدد النساء بيزيد وعدد الرجال بيقل،\nحتى في حديث رسول الله ﷺ إن هييجي زمان هيبقى في مقابل خمسين امرأة رجل واحد هو إللي بيراعيهن،\nوربنا مُعطي الرجل بصفة عامة القدرة والقوة على الزواج بأكثر من امرأة،\nفموضوع إن الرجل يتزوج أكثر من امرأة ده في الشرع والعرف شيء عادي و《مُباح》 مش إلزامي ولا هو فرض ماشي\n◇ثانيا:\nزواج رسول الله ﷺ من زوجاته كان معظمه من الوحي ولأهداف مهمة منها: \nإنه يجبر بقلب الأرامل وتعويضهن عن فقد أزواجهن في الجهاد، وهو بكده شرع سنة الإحسان للنساء إللي فقدن أزواجهن في الجهاد، \nومنها : \nتكثير المُعلمات والمُوجهات للأمة من خلال سيرته الداخلية، يعني زوجات رسول الله ﷺ بشخصيات مختلفة،\nوقبائل مختلفة وأعمار مختلفة، \nكل واحدة فيهن محتاجة معاملة شكل، فلما رسول الله ﷺ يتعامل مع الشخصيات دي كلها وهن ينقلن حياته وتصرفاته للأمة من بعده،\nهيبقى سهل إن المسلمين يطبقوا تعاملاته سواء في الحياة الزوجية أو في أمور العبادة، فيبقى في صورة متكاملة عن حياة رسول الله ﷺ بين إيدنا عشان نقدر نتبعه صح\nومع إن رسول الله ﷺ كان مشغول خلال الكم شهر دول بسبب زواجه من امرأتين، وتزويجه لابنته، وكان مشغول مع أصحابه في تربيتهم الإيمانية، وهو نفسه كان مشغول في عبادته،\n وكمان في شهر رمضان وَلَدت فاطمة ابنته أول طفل لها وهو الحسن بن علي بن أبي طالب، \nكل الأحداث إللي وراء بعضها دي لم تُشغل رسول الله ﷺ عن قريش إللي كانت بتخطط وترتب عشان تنتقم من المسلمين للي حصل لها في غزوة بدر\nنروح نشوف أهل مكة وصلوا بخططهم وترتيباتهم لحد فين \nاتفق أهل مكة إنهم هياخدوا أموال قافلة أبو سفيان إللي نجت من المسلمين في بدر عشان يجهزوا بها جيش يحارب المسلمين، وكانت قيمتها خمسين ألف دينار ذهبي\nإنتم عارفين حرب يعني محتاجين سلاح، ومحتاجين خيل، ومحتاجين دروع ومؤونة، يعني أكل وشرب،\nبدأوا يجهزوا الجيش من داخل مكة وكمان من خارجها، وكأن لسان حالهم يقول : \nمانتم لازم تساعدونا في القضاء على المسلمين، وإلا الدور هييجي عليكم\nوطبعا انتم عارفين إن القبائل أهم حاجة عندهم ملكهم \nفبدأوا يساعدوا أهل مكة شوية بالرز أقصد بالمال\nوشوية بالشباب عشان يحاربوا معاهم،\nوطبعا مننساش دور الإعلام\nوده كان بقيادة واحد اسمه أبو عزة الجُمَحِي وإللي كان شاعر، فكان بيحفز القبائل ضد المسلمين ويحمس الناس: \nيا جماعة انزلوا عشان تحاربوا محمد وأصحابه إللي قتلوا سادات مكة،\nإللي ضيعوا مكة وفرقوا بين أهلها، وهم السبب في الأزمات إللي احنا فيها دلوقتي دي، و....وأظن إنتم عارفين الباقي بقى \nتخيلوا إن أبو عزة الجمحي ده كان واحد من إللي المسلمين أسروهم يوم بدر، فقعد يقول لرسول الله ﷺ انا عندي بنات يا محمد وملهمش غيري وأنا فقير، \nوقعد يستعطف رسول الله ﷺ لحد ما رسول الله ﷺ رقّ له وأطلقه من غير فداء،\nيعني من غير ما يدفع أموال مقابل إطلاق سراحه، لكن رسول الله ﷺ اشترط عليه إنه لا يحارب ضد المسلمين ولا يُحَفّز المشركين ضد المسلمين\nفوافق أبو عزة الجُمحي، ولكنه طلع بعد كده غادر ولئيم، فنقض العهد مع رسول الله ﷺ يحفز الناس ضد رسول الله ﷺ\nورسول الله ﷺ يا جماعة بشر لا يعلم الغيب، كان هيعرف منين إن أبو عزة ده غادر \nطبعا لو كان رسول الله ﷺ عايش معاه وشاف علامات من غدره كان هياخد موقف فورا، \nمكنش هيسيبه لحد ما يشوّه سمعته ويخلي الناس تبقى ضده\n☆على فكرة أبو عزة ده المسلمين هيأسروه بعدين، وهيقعد برده يستعطف رسول الله ﷺ، لكن رسول الله ﷺ قال لأبو عزة: والله ما أسيبك تزهو بنفسك وتستخف بي في مكة وتقول : خدعت محمد مرتين\nلا يُلدغ المؤمن من جحر واحد مرتين، اضرب عنقه يا زيد\nياريت نتعلم من رسول الله ﷺ بقى\nأيوة رسول الله لا يعلم الغيب بس بياخد قرارات حاسمة حازمة وقت اللزوم، \nحتى لو كانت قتل وخصوصا لو واحد زي أبو عزة ده، وده في صلاحياته عادي، ما هو الحاكم يا جماعة \nالمهم اتجمع لجيش المشركين ثلاثة آلاف مقاتل، جيش لم يتجمع في جزيرة العرب قبل كده نهائي\nومش بس كده، ده خرج مع الجيش خمسة عشرة امرأة منهن زوجة صفوان بن أمية، \nوزوجة عكرمة بن أبي جهل تقودهن سيدة مكة الأولى هند بنت عتبة زوجة أبو سفيان حاكم مكة\nوهند تبقى بنت عتبة بن ربيعة الرجل الحكيم إللي منفعتهوش حكمته لأنه مكنش سيد قراره وقُتل يوم بدر هو وابنه الوليد وأخوه شيبة بن ربيعة،\nفكده هند مات لها أبوها وأخوها وعمها، فكانت من أكثر النساء قهرة وغيظ من المسلمين وخصوصا من حمزة بن عبد المطلب لأن هو إللي قتل أبوها واشترك في قتل أخوها الوليد،\n☆والقصة المشهورة إن هي كان عندها عبد اسمه وحْشي بن حرب، وقالت له لو إنت قتلت حمزة سأعتقك غير صحيحة\nالحديث في البخاري إن إللي قال لوحشي بن حرب لو قتلت حمزة سأعتقك هو جُبير بن المطعم بن عدي، لأن حمزة قتل عمه في غزوة بدر، فكان جُبير عايز ينتقم منه،\nفقال لوحشي بن حرب لو قتلت حمزة فأنت حر، لكن هند ملهاش علاقة بالموضوع نهائي، والقصة المشهورة عنها إنها أكلت كبد حمزة غير صحيحة إطلاقا\nهنتكلم عنها بالتفصيل لما ييجي وقتها إن شاء الله \nتجهّز جيش المشركين وخرجوا من مكة في اتجاه المدينة إللي على بعد خمسمائة كيلو متر من مكة،\nيا ترى المسلمين عملوا إيه واتجهزوا إزاي في مواجهة أكبر جيش يتجمع في جزيرة العرب؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 97, "l": "الجزء 71 | تجهيز جيش المسلمين لغزوة احد", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الواحدة_والسبعون\n#تجهيز_جيش_المسلمين_لغزوة_أحد\nاتكلمنا المرة إللي فاتت عن تجهيزات جيش المشركين وخروجهم من مكة وتوجههم  للمدينة لحرب المسلمين،\nطبعا تجهيزات المشركين مكنتش في يوم وليلة\nده كانوا بيجهزوا للحرب دي من بعد غزوة بدر على طول،\nيعني غزوة بدر كانت في رمضان من السنة الثانية للهجرة،\nوغزوة أحد كانت في السابع من شوال من السنة الثالثة للهجرة،\n يعني قعدوا تقريبا سنة يجهزوا للمعركة دي\nورسول الله ﷺ في وسط الإنشغالات إللي كان فيها كان عارف تخطيط قريش ونيتهم في الهجوم على المسلمين فكان بيجهز برده المسلمين على حسب قدرته وقدرة المسلمين معاه خلال السنة دي،\nلكن كان في عقبات\nانتم عارفين إن من الحكمة إن الحاكم عشان يقدر يتفرغ للعدو الخارجي إللي بيهدد بلده، لازم يقضي على عدوه الداخلي الأول،\nيعني رسول الله ﷺ مينفعش يسيب المدينة وهي فيها أعداء ظاهرين ويروح يقاتل قريش إللي بعيد عنه،\nلأن خطر العدو الداخلي أشد من العدو الخارجي \nأعداء رسول الله ﷺ والمسلمين في المدينة هم اليهود والمنافقين والمشركين،\n◇اليهود خليناهم على الحياد بمعاهدة صلح، وإللي تمرد منهم ونقض المعاهدة طلعناه برة المدينة زي يهود بني قينقاع.\n◇المنافقين كانوا بيتكلموا من تحت لتحت عشان ميلفتوش النظر لهم،\nلكن ربنا العالم بكل شيء حذر المسلمين في آيات القرآن عشان ياخدوا بالهم من الناس دي،\nخلونا نشوف ربنا قال إيه للصحابة في سورة آل عمران\nقال:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا وَدُّوا مَا عَنِتُّمْ قَدْ بَدَتِ الْبَغْضَاءُ مِنْ أَفْوَاهِهِمْ وَمَا تُخْفِي صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ الْآيَاتِ ۖ إِن كُنتُمْ تَعْقِلُونَ\"\nيعني إيه الكلام ده\nربنا بيقول للمسلمين وبيحذرهم إنهم ياخدوا بالهم من أصحابهم إللي بيقربوهم هم إيه،\nلأن المجتمع في المدينة كان كله سايح على بعضه، يهود ومشركين ومنافقين ومؤمنين،\nفكان رجال من المؤمنين مصاحبين اليهود والمنافقين ويستشيروهم في أمورهم ويعطوهم الأمان،\nلأن كان أي حد يقول لا إله إلا الله كان بالنسبة لهم خلاص انت بقيت زينا، ومكنوش يعرفوا حاجة عن المنافقين لسه، \nأما اليهود فكان بينهم قرابة وأخوة في الرضاعة،\nوكان بينهم معاهدات وصداقات،\nفالمؤمنين كانوا بيتعاملوا بصفاء نية على أساس الود إللي كان بينهم قبل الإسلام،\nفربنا العليم بذات الصدور بيقول لهم لأ.. مينفعش تتخذوا أولياء وأصحاب مقربين وهم مش على نفس دينكم أو نفس منهجكم الصحيح،\nالناس دي بيتمنوا لكم الشر والهلاك وكل الضرر، ومش هيقصروا في إنهم يعملوا كل حاجة تخليكم ترجعوا للشر والفساد تاني،\n\"وَدُّوا مَا عَنِتُّمْ\"\nوظهر في كلامهم علامات العداوة دي من إطلاع المشركين على أسرار المؤمنين، والوقيعة بين المسلمين،\nوإللي في صدورهم من الغيظ والعداوة أكبر من إللي ظاهر\n\" قَدْ بَدَتِ الْبَغْضَاءُ مِنْ أَفْوَاهِهِمْ وَمَا تُخْفِي صُدُورُهُمْ أَكْبَرُ ۚ\"\nشوفوا إنتم بتحبوهم إزاي بسبب الود إللي كان بينكم، لكن هم بقى مش بيحبوكم بسبب إنكم بقيتم على دين مختلف عنهم، مع إن إنتم تؤمنون بكل الكتب أصلا\n\"هَا أَنتُمْ أُولَاءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِالْكِتَابِ كُلِّهِ وَإِذَا لَقُوكُمْ قَالُوا آمَنَّا \"\nولما يقابلوكم يقولوا لكم احنا آمنا طبعا\nوأول ما يكونوا مع بعض لوحدهم يقعدوا يعضوا على أطراف أصابعهم من الغيظ منكم، بسبب حبكم لبعض واجتماعكم على الصح\n\"وَإِذَا خَلَوْا عَضُّوا عَلَيْكُمُ الْأَنَامِلَ مِنَ الْغَيْظِ ۚ قُلْ مُوتُوا بِغَيْظِكُمْ ۗ إِنَّ اللَّهَ عَلِيمٌ بِذَاتِ الصُّدُورِ\"\n☆ولو حبينا نربط القرآن بالواقع بتاعنا هتلاقوا أمثلة كثيرة في حياتنا، كم شاب أو بنت فكروا يلتزموا بالطاعات ويبعدوا عن المعاصي ولقوا من أصحابهم وحتى من أهلهم إللي يثبطهم ويقول لهم انت هتعمل فيها شيخ،\nانتِ مش هتقدري تكملي في الطريق ده، \nسيبك من الكلام ده وشوفي انتِ كنتِ بتعملي إيه، وسخرية واستهزاء وحرق دم\nأهه ربنا بيقول لنا محدش يكون له بطانة على غير منهجه وطريقه الصحيح\nوكلمة بطانة دي لها معنى عميق\nعارفين بطانة الثوب، يعني لما نشتري أي لبس مش بتكون له بطانة داخلية، أو مثلا لما بتكون قماشة مش حلوة بنقول نعملها بطانة مريحة،\nلأن البطانة دي هي إللي هتكون على الجلد على طول، فبنكون محتاجين حاجة طرية ناعمة مريحة على الجلد، أهه ربنا شبّه الصحبة بالبطانة، \nيعني أصحابنا المقربين هم زي بطانة الملابس، لازم نختار بطانة صالحة من البشر زي ما بنختار بطانة الملابس الطرية على الجلد\nفاللي نلاقيه بيؤذينا بالكلام وبيثبط من عزيمتنا وبيحاول بكلامه وبأفعاله يبعدنا عن الطريق الصحيح ويبذل جهده في كده، ناخد بالنا ونَحذر ونبعد عن الشخص ده، ونعرف إنه مينفعش يكون بطانة لينا ،ونفتكر على طول كلام ربنا:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا \" \nفكان رسول الله ﷺ بيربي المؤمنين من خلال القرآن التربية الإيمانية دي، لأن التربية الإيمانية للمسلمين هي الأساس لأي معركة\nييجي بعد كده الإعداد المادي، يعني ربنا بيقول للمسلمين:\n\" وَأَعِدُّوا لَهُم مَّا اسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللَّهِ وَعَدُوَّكُمْ \"\nفمحتاجين القوة والسلاح والتنظيم، وصل الخبر لرسول الله ﷺ إن قريش خرجت من مكة ومتجهة نحو المدينة،\nوطبعا زمان مكنش في مواصلات فكانوا بيمشوا على رجلهم\nفهياخدوا وقت على ما يوصلوا المدينة، فكان في الوقت ده رسول الله ﷺ بدأ يأخذ خطوات عشان يستعد للحرب.\nيا جماعة الاستعداد الإيماني كان مستمر على طول مكنش بيقف، لأن القلب محتاج شحنات إيمانية مستمرة عشان يقدر يواجه الابتلاءات بصفة عامة\nدلوقتي بقى جينا للاستعداد المادي عايزين خطوات عملية عشان نشوف هندافع عن المدينة إزاي،\nأول حاجة عملها رسول الله ﷺ إنه جمع الصحابة عشان يتشاور معاهم يعملوا إيه\nودي أول صفة من صفات الجيش المنصور، لما اتكلمنا عن غزوة بدر قلنا إن الشورى وعدم الاستبداد بالرأي كانت سبب من أسباب انتصار المسلمين في بدر،\nفهنلاقي هنا برده إن رسول الله ﷺ بيشاور أصحابه،\nأول حاجة اتفقوا عليها قبل ما يخططوا إزاي هيحاربوا إنهم يُأمّنوا المدينة ويأَمّنوا رسول الله ﷺ، \nلأن المشركين ممكن يرسلوا حد يغتال رسول الله ﷺ،\nفعملوا فِرق حماية زي دوريات كده،\nفرقة تمشي مع رسول الله ﷺ في كل مكان تحميه، \nوفرق تحمي أبواب المدينة عشان محدش يهجم فجأة على المسلمين.\n☆ممكن حد يسأل، طيب ماهو ربنا ممكن يحمي رسوله عادي، وخصوصا إنه لسه مكملش رسالته فهو مش ممكن يموت دلوقتي\nأيوة فعلا ربنا ممكن يحمي رسول الله ﷺ بمعجزة، لكن احنا اتفقنا إن رسول الله ﷺ قدوة لكل الناس إللي هتيجي من بعده،\nحكام ومحكومين، فرسول الله ﷺ بيعلمنا إزاي نتعامل مع المواقف إللي ممكن يتعرض فيها الحاكم المسلم للخطر، وإن الأخذ بالأسباب لا ينافي التوكل على الله\nومن الأخذ بالأسباب إن المسلمين وضعوا دوريات استطلاع حول المدينة عشان يرصدوا تحركات جيش المشركين،\nوكان المسلمون داخل المدينة مش بيتحركوا إلا والسلاح معاهم حتى وهم في الصلاة،\nفاحنا شايفين الاستعداد التام لأي حاجة ممكن تحصل، ودي الصفة الثانية من صفات الجيش إللي ربنا ينصره، الاستعداد الجيد للمعركة\nنيجي بقى لاستراتيجية الحرب، عندنا اختيارين دلوقتي،\n◇الاختيار الأول:\n إننا نستنى المشركين لما ييجوا ويدخلوا المدينة ونحاربهم حرب شوارع،\nوهنا في ميزة إن كل أهل المدينة حتى النساء يقدروا يشاركوا في الحرب من فوق البيوت، ومن غير ما يتعرضوا للأذى، وخصوصا لو كان عدد الجيش المدافع أقل من عدد الجيش المهاجم،\nزي ماحنا شايفين دلوقتي، المشركين جايين بجيش من ثلاثة آلاف مقاتل،\nفحرب المدن بتكون صعبة على الجيوش إللي ماشية على الأرض، لكن في نفس الوقت فيها عيب قاتل\nإن لو المسلمين انهزموا فجيش المشركين هيسيطر على المدينة وتبقى مذبحة\n◇الاختيار الثاني:\nإننا نطلع للمشركين برة المدينة ونقاتلهم بعيد عن المدينة، بحيث إننا لو اتهزمنا تبقى المدينة في أمان ويبقى في مكان للمسلمين يرجعوا له، ويرتبوا صفوفهم من تاني\nلكن المشكلة إن أعداد المشركين أكثر  وسلاحهم أكثر،\nفكل اختيار له مميزاته وله عيوبه\nقبل ما يأخذوا أي قرار، رسول الله ﷺ قال لهم إنه رأى رؤيا،\nقال :\nرأيت بقرا تُذبح، ورأيت في طرف سيفي خدش أو كسر، ورأيت أني أدخلت يدي في درع حصينة\nفالصحابة سألوه :\nإيه تأويل الرؤيا يا رسول الله\nفقال لهم رسول الله ﷺ:\nالبقر إللي تذبح أوّلتها بإن في مجموعة من أصحابي هيُقتلوا،\nوطرف السيف إللي فيه كسر أو خدش فأوّلته إن في رجل هيُقتل من أهل بيتي،\nأما الدرع إللي أدخلت فيها يدي فأوّلتها المدينة، \nيعني يقصد إنه يقاتل في المدينة المنورة، فدلوقتي رسول الله ﷺ رأيه الشخصي إنه يقاتل في المدينة،\nوهو بيقول الرؤيا على أساس إنه يعرض رأيه مش بيلزمهم به، ولو كانت الرؤيا وحيا ملزما، يعني لازم يقاتلوا في المدينة مكنش استشارهم أصلا\nلأن الوحي واجب التنفيذ\nلكن هنا الموضوع على حسب المشورة، فقال لهم صراحة :\nأنا رأيي نقاتل في المدينة، المسلمين على أطراف الشوارع والنساء من فوق البيوت\nالمسلمين كان رأيهم إيه بقى\nمعظم المسلمين وخصوصا إللي محضروش بدر كان رأيهم عكس رأي رسول الله ﷺ، كانوا عايزين يقاتلوا المشركين خارج المدينة،\nحتى إن واحد منهم قال : \nيا رسول الله! كنا نتمنى اليوم ده وندعوا الله، وربنا استجاب لنا، فخلينا نخرج لأعدائنا، وعشان ميفكروش إننا خفنا منهم\nفكان المسلمون متحمسون للخروج، وطبعا معاهم حق لأن معنوياتهم كانت عالية، انتصروا على المشركين في بدر،\nوأخذوا قافلة صفوان بن أمية،\nوالعرب بقت تخاف منهم، فكان وضع المسلمين ممتاز جدا، وكان من ضمن المتحمسين حمزة بن عبد المطلب رضي الله عنه، لدرجة إنه قال لرسول الله ﷺ:\nوالله ما آكل شيء حتى أقاتل المشركين خارج المدينة\nكل الآراء تتجه للقتال خارج المدينة،\nمين إللي كان رأيه من رأي رسول الله ﷺ وكان عايز القتال يبقى في المدينة\nعبد الله بن أُبي بن سلول زعيم المنافقين\nهو مكنش مقتنع بقى برأي رسول الله ﷺ وإنه عايز مصلحة المسلمين، ده كان بيدور على مصلحته\nلو جيش المسلمين قاتل في المدينة هيبقى سهل عليه إنه يهرب هنا ولّا هنا ومحدش شايف حاجة،\nلكن لو الجيش خرج برة المدينة هيبقى واضح مين حضر ومين غاب\nرسول الله ﷺ نزل على رأي الأغلبية، مع إن هو مكنش موافق، لكن مدام الموضوع مش وحي إلزامي والموضوع شورى فخلاص يبقى ننزل على رأي الشورى\n☆متخيلين رسول الله ﷺ وهو رسول الله يتنازل عن رأيه عشان خاطر رأي الأغلبية إللي هي عكس رأيه\nوده مش خروجة ولا لبس هنشتريه، دي حرب يعني أي خطأ فيها بموت على طول، ومع ذلك نزل على رأي الأغلبية\nأظن محتاجين نعيد حسابتنا تاني ونتعلم احترام آراء الآخرين، ونبطل ثقافة مادام أنا شايف كذا يبقى رأيي هو الصح،\nوأحارب الناس واعترض عشان ينفذوا رأيي لمجرد إني شايف إني أنا الصح وعايز حاجة معينة\n◇ملحوظة مهمة\nالكلام زي مانتم شايفين في حاجات مُباحة فيها أخذ ورد ورأي، لكن الحاجات الشرعية إللي عليها دليل مفيهاش كلام نهائي، احنا نقطع عرق ونسيّح دم على طول \nرسول الله ﷺ لو كان عنده وحي بعدم الخروج من المدينة مكنش هيخرج إطلاقا،\nولا حتى كان هيعرض الموضوع على الصحابة، وحتى الصحابة نفسهم محدش فيهم كان هيعترض، \nكانوا هيقولوا سمعنا وأطعنا على طول بدون أي نقاش\nصلى رسول الله ﷺ الجمعة مع الصحابة في السادس من شوال من السنة الثالثة من الهجرة ووعظهم في خطبة الجمعة، وبشرهم بالنصر لو هم\n《صبروا وأطاعوا الله وأطاعوا أمر رسوله ﷺ》\nالناس فرحوا بالخروج لقتال المشركين وبدأوا يتجهزوا، \nوصلى رسول الله ﷺ بهم العصر وجمع الناس وحشد الجيش عشان يستعدوا للخروج،\nوبدأ هو نفسه ﷺ يستعد للخروج، ولبس عُدة الحرب وكان في كل حرب بيلبس درع عشان يحميه من السهام وضربات العدو، لكن المرة دي لبس درعين\nفي الوقت إللي كان رسول الله ﷺ بيتجهز اجتمع الأنصار مع المهاجرين وبدأوا يتكلموا مع بعض: \nقال لهم سعد بن معاذ وأُسيد بن حُضير : \nاستكرهتم رسول الله ﷺ على الخروج، فردوا إليه الأمر\nيعني إنتم فرضتم رأيكم على رسول الله ﷺ وأكرهتوه على الخروج وهو مش عايز،\nفالصحابة حسوا إن برأيهم خالفوا رأي رسول الله ﷺ\nأيوة رسول الله ﷺ سمح بالشورى لكن هو رسول الله ﷺ، وكلهم عارفين إن رأيه هو الأحكم والأفضل حتى لو كان مخالف لرأيهم،\nفاستحيوا إزاي نخالف رأي رسول الله ﷺ \nوقالوا احنا هنخلي رسول الله ﷺ هو إللي ياخد القرار النهائي\n☆واخدين بالكم\n الصحابة مكسوفين إنهم يقولوا رأي مخالف لرأي رسول الله ﷺ مع إنه هو إللي أَذِن لهم إنهم يقولوا رأيهم، \nومفيش 《نص شرعي》 في الموضوع يعني الموضوع عادي جدا،\nومع ذلك اتكسفوا وقالوا لأ ننزل على رأي رسول الله ﷺ،\nرأي رسول الله ﷺ هو الأفضل،\nمش ناس يجيلها الأمر المباشر من رسول الله ﷺ يقعدوا يقولوا ليه وعشان إيه واشمعنى، وأصلا زمن الرسول غير زماننا و...و...وحاجات تشل بصراحة،\nوإللي يجنن الواحد أكثر إنهم ييجوا يسألوا اشمعنى الصحابة يعني إللي لهم الأجر الكبير ده وإن مفيش حد زيهم في المنزلة\nأظن عرفنا ولو قليل ليه محدش هيبقى زي الصحابة أبدا في المنزلة \n☆طبعا ممكن حد يسأل طيب وحديث إن لنا أجر خمسين صحابي ده إيه\n \nلو تفتكروا في البداية خااالص شرحناه بس انا هقوله تاني عشان تفتكروه، وفي الإعادة إفادة \nقال رسول الله ﷺ :\n\"إن من ورائكم أيام الصبر ، 《للمتمسك فيهن》 يومئذ بما أنتم عليه أجر خمسين منكم  قال :\nيا نبي الله ! أَوَمنهم ؟ قال : ((بل منكم ))\nده مش معناه إن في حد هيكون أفضل من الصحابة،\nلأن الصحابة لهم أجرين : أجر العمل وأجر صحبة رسول الله ﷺ .\nوكمان رسول الله ﷺ قال: 《للمتمسك》\nيعني واحد متمسك بدينه مش بياخد من الدين إللي على هواه وبس، \nبيعمل زي الصحابة فيأخذ زي أجر خمسين من الصحابة بسبب إن《 التمسك》 بدينه ده مش هيلاقي أحد يعينه وهيتحارب من كل الجهات لكنه هيفضل متمسك بدينه \nفعشان كده ربنا هيعطي له أجر خمسين واحد من الصحابة ومش معنى إن الأجر أكثر منهم يبقى إللي أجره أعلى يكون أفضل ،\nوخصوصا إن رسول الله ﷺ قال :\n\"والذي نفسي بيده لو أن أحدكم أنفق مثل أحد ذهبا ما أدرك مُدّ أحدهم ولا نصيفه\"\nيعني لو أنفق واحد فينا زي جبل أحد ذهب مش هياخد نص أجر واحد منهم تصدق بطعامه\nخرج رسول الله ﷺ من الخيمة لقاهم متجمعين، فقالوا له:\n يا رسول الله! احنا عمرنا ما نخالفك أبدا، اعمل إللي انت عايزه، لو عايز تفضل في المدينة ونقاتل فيها عادي\nرسول الله ﷺ رد عليهم وقال:\nما ينفعش لنبي بعد ما لبس ملابس الحرب إنه يخلعها حتى يحكم الله بينه وبين عدوه\nيعني خلاص، مينفعش يبقى في تردد وكل شوية برأي، أخذنا القرار ورتّبنا نفسنا عليه وانتهى الموضوع\nاتجمع الجيش وبدأ رسول الله ﷺ يقسمه لكتائب ويستعرض الجيش ويشوف مين إللي يصلح للجهاد ومين لأ،\nقسم الجيش لثلاثة كتائب : \n◇كتيبة المهاجرين وجعل قائدهم إللي معاه الراية مصعب بن عمير، \n◇الكتيبة الثانية:\n كتيبة الأوس وجعل قائدها أُسَيد بن حُضير إللي قال لرسول الله ﷺ لو كنت أعرف إن في قتال كنت خرجت معاك فرسول الله ﷺ قال له : صدقت،\nوأسيد بن حضير هو الصحابي إللي أسعد بن زرارة قال لمصعب اصدق الله في دعوته، وأسلم أسيد على يد مصعب،\nهم الإثنين دلوقتي طالعين مع بعض في معركة واحدة\n◇الكتيبة الثالثة :\nكتيبة الخزرج قائدها الحُباب بن المنذر.\nجهز رسول الله ﷺ المسلمين بمائة درع، ومكنش عندهم خيول إلا أعداد قليلة جدا،\nفهو جهز الجيش باللي يقدر عليه وفي استطاعته، وهو بيشوف الصفوف لقى من ضمن الجنود في .....في إيه\nهنعرف الجزء الجاي إن شاء الله \n☆"}, {"n": 98, "l": "الجزء 72 | اختيار أرض المعركه | أخبار بعض من خرج ف غزوة أحد", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثانية_والسبعون\n#اختيار_أرض_المعركة\n#أخبار_بعض_من_خرج_في_غزوة_أحد\nاتكلمنا المرة إللي فاتت عن تجهيز رسول الله ﷺ لجيش المسلمين وقلنا إنه قعد يستعرض الجيش عشان يشوف لو فيه خلل، أو في حد لا يصلُح للقتال،\nفا وهو بيشوف الجيش إللي كان عدده ألف رجل شاف أطفال في الجيش جايين عايزين يجاهدوا مع رسول الله ﷺ\nزي أسامة بن زيد بن حارثة إللي كان عمره حوالي من تسعة إلى عشرة أعوام،\nوأسامة يعتبر حفيد رسول الله ﷺ لأن أبوه زيد كان تبناه رسول الله ﷺ وبقى اسمه زيد بن محمد لحد ما اتحرم التبني، وكان رسول الله ﷺ بيحبه هو وأبوه،\nوكان أسامة يُسمى الحِبّ بن الحِبّ،\nوكان من الأطفال في الجيش عبد الله بن عمر بن الخطاب، وأبو سعيد الخدري،\nوكان رسول الله ﷺ بيرد عن الجهاد أي حد تحت سن خمسة عشرة عاما، \nلأن من صفات الجيش المنتصر توْسِيد الأمر إلى أهله،\nيعني إني أعطي المسؤولية للي يقدر يتحملها من غير واسطة أو محسوبية أو عشان أنا بحب فلان أو لأ\nومن علامات يوم القيامة أن يُوَسّد الأمر لغير أهله، يعني واحد مبيفهمش في الاقتصاد نلاقيه متعيّن في أعلى مناصب الاقتصاد،\nواحد مش عارف يبقى مسؤول عن فرخة نلاقيه بقى مسؤول عن ملايين البشر وهكذا\nجاء رجل لرسول الله ﷺ يسأله متى الساعة؟\nقال له رسول الله ﷺ: \nإذا ضُيعت الأمانة فانتظر الساعة، قال: كيف إضاعتها؟ قال: إذا وُسّد الأمر إلى غير أهله.\"\nفرسول الله ﷺ كان بيعطي المسؤولية للي يقدر عليها فعلا وهو عارف إن دول أطفال مش أد المسؤولية،\nلكن دايما في شواذ للقاعدة \nواحد من صغار الصحابة اسمه رافع بن خديج كانت قدرته في الرماية ممتازة على الرغم من إن عمره كان ثلاثة عشر عاما إلى أربعة عشرة عام، فوافق رسول الله ﷺ إنه يخرج معاه في الغزوة،\nواحد تاني من صغار الصحابة اسمه سَمُرَة بن جُنْدَب كان عمره أقل من خمسة عشرة عام هو كمان قال لرسول الله ﷺ :\nاشمعنى رافع، أنا أقوى من رافع خليني أصارعه يا رسول الله وهتشوف إني أقدر أغلبه \nفقال لهما رسول الله ﷺ خلاص تصارعا، عشان يختبر قدراتهم القتالية،\nفلما تصارعا غلب سَمُرة رافعا، فوافق رسول الله ﷺ إن سمرة يخرج معاه للجهاد زي رافع،\nوجاء رسول الله ﷺ  واحد من الصحابة اسمه عمرو بن الجَمُوح، كان من سادات الأنصار عايز يخرج يجاهد معاه، لكن الصحابي ده عنده عَرج في رجله،\nيعني بيمشي يعرج، فأبناءه قالوا له ربنا عذرك مش فرض عليك الجهاد\nوكان حاول يخرج مع رسول الله ﷺ في غزوة بدر لكن أبناؤه منعوه لنفس السبب،\nلكنه المرة دي صمم إنه يخرج وذهب لرسول الله ﷺ يشتكي أبناءه وإنه عايز يخرج،\nفرسول الله ﷺ قال له : \nإنت عندك عذر، الجهاد مش فرض عليك، فقال له عمرو بن الجموح :\nأنا عايز أطأ الجنة بعرجتي هذه، يعني عايز أدخل الجنة بعرجتي دي،\nفوافق رسول الله ﷺ وأذن له إنه يخرج معاه للجهاد.\n☆عارفين عمرو بن الجموح ده كان آخر واحد أسلم من الأنصار ومع ذلك شوفوا إصراره على الخروج للجهاد مع إنه معذور\nربنا بيقول:\n\"ليْسَ عَلَى الْأَعْمَىٰ حَرَجٌ وَلَا عَلَى الْأَعْرَجِ حَرَجٌ وَلَا عَلَى الْمَرِيضِ حَرَجٌ\"\nوقصة إسلامه عجيبة، لما مصعب بن عمير جاء للمدينة وبدأ يدعو الناس للإسلام، وكان أبناء عمرو بن الجموح ممن سابقوا للإسلام وكانوا ممن حضر  بيعة العقبة الثانية،\nوأسلمت زوجته وأخوها عبد الله بن حرام إللي كان صديق مقرب منه ومش بس زوج أخته، ومع ذلك عمرو بن الجموح لم يُسلم\nوكان عنده صنم اسمه مناف بيعبده، فكان معاذ ابنه وصاحبه اسمه معاذ بن جبل بيدعوا الناس للإسلام،\nفاستعملوا الحيلة مع عمرو بن الجموح عشان يبينوا له بالعقل إن الصنم إللي بيبعده ده لا يضر ولا ينفع،\nفكان معاذ بن عمرو وصاحبه معاذ بن جبل كل يوم بالليل يأخذوا الصنم مناف بتاعه ده ويرموه في حفرة من الحفر إللي الناس بترمي فيها الفضلات،\nيقوم عمرو بن الجموح الصبح مش لاقي الصنم بتاعه\nيقعد يدوّر عليه لحد ما يلاقيه مرمي في الحفرة فيغضب ويزعق ويقول :\nمين إللي تعدى على الإله بتاعنا\nفيأخذه ويغسله وينظفه ويُعطره، ولما ييجي الليل يكرر المُعاذان نفس الفعلة، لحد ما زهق عمرو بن الجموح، فجاء بسيف وعلقه في رقبة الصنم وقال له:\nشوف، لو حد جاءك عشان يؤذيك دافع عن نفسك بالسيف\nصحي تاني يوم الصبح ملقاش الصنم، لقاه في الحفرة ومش بس كده ده لقاه مربوط في كلب ميت\nفا وهو قاعد غضبان ومتضايق رآه بعض أشراف المدينة من المسلمين فقعدوا يفهموه مين هو الإله العظيم الذي ليس كمثله شيء، \nوإزاي يكون إله ومش قادر يدافع عن نفسه، فكلموه عن الإسلام وعن رسول الله ﷺ، فقام عمرو بن الجموح وتطهر وتطيب وذهب لرسول الله ﷺ ليبايعه على الإسلام،\nوكان لما أسلم على مشارف الستين من عمره،\nولما طلب إنه يخرج للجهاد مع رسول الله ﷺ في غزوة أحد كان في الستين من عمره،\nمقلش خلاص بقى أنا ربنا عذرني وممكن آخذ بالرخصة وأقعد،\nأو أنا رجل كبير في السن ومش هقدر أجاهد أصلا، الناس دي مكنتش بتفكر كده، الناس دي كانوا عارفين إن الحسنة الواحدة هتفرق معاهم فمكنوش بيضيعوا أي حسنة ممكن تقربهم من ربنا\nلما كان رسول الله ﷺ بيجهز الجيش جاءه عبد الله بن أبي بن سلول ومعاه كتيبة من المقاتلين، فسأل رسول الله ﷺ مين الناس دي؟\nقالوا له: ده عبد الله بن أبي بن سلول ومعاه مواليه من اليهود، يعني حلفاء عبد بن أبي بن سلول جايين يقاتلوا معاه عشان بينهم عهد،\nفرسول الله ﷺ قال : هل أسلموا؟\nفقالوا له : لأ\nفقال لهم رسول الله ﷺ:\nارجعوا فإني لا أستعين بمشرك\n☆طيب ليه رسول الله ﷺ رفض إنه يستعين بمساعدة غير المسلمين، مش المفروض يستغل أي حاجة ممكن تساعده على النصر، وخصوصا إن عدد جيش المسلمين قليل بالنسبة لعدد جيش المشركين\nعندنا قاعدة مهمة في دين الإسلام وهي دَرْء المفسدة مُقدّم على جَلْب المصلحة،\nزي ما اتكلمنا قبل كده وقلنا إن رسول الله ﷺ لم يقتل المنافقين عشان محدش يقول إن محمد يقتل أصحابه،\nففي مصلحة من قتل المنافقين عشان نخلص من شرهم، لكن في مفسدة في قتل المنافقين وهي تشويه صورة الإسلام،\nفرسول الله ﷺ قدم درء المفسدة، يعني إبعاد المفسدة،\nفهنا برده عمل نفس القاعدة،\nفي مصلحة من وجود اليهود في جيش المسلمين بإنهم يقاتلوا معاهم، لكن في مفسدة وهي إن أهل الكفر بصفة عامة وخاصة اليهود بيكرهوا المسلمين،\nفمن المؤكد إنهم هينتهزوا أي فرصة عشان يضروا بالمسلمين، ومش بعيد في وسط الحرب ينضموا لصفوف أعداء المسلمين وينقلوا لهم أسرار المسلمين الحربية فيحصل إبادة للمسلمين\nماهي الحرب فيها خطط لازم الجنود يعرفوها وإلا إزاي هيتحركوا في أرض المعركة\nفلما يكون في كتيبة كاملة غير مؤتمنة ممكن تخون المسلمين في أي لحظة، ليه أستعين بها من الأصل وأعرض الجيش كله للهلاك\nفي بعض العلماء قالوا إن ممكن الإستعانة بالمشرك بشورط معينة منها:\nإن عدد المسلمين وعتادهم كبير جدا، وإن يُؤمن خيانة المشرك ده، وأن يعرف الإمام حُسْن رأيهم في حالات الضرورة،\nيعني تقريبا شروط شبه مستحيلة\nفالأصل إن المسلم لا يستعين بالكافر زي ما رسول الله ﷺ رفض الاستعانة بالكافرين\nوشوفوا ربنا بيقول إيه :\n\"لَوْ خَرَجُوا فِيكُمْ مَا زَادُوكُمْ إِلا خَبَالا وَلأَوْضَعُوا خِلالَكُمْ يَبْغُونَكُمُ الْفِتْنَةَ وَفِيكُمْ سَمَّاعُونَ لَهُمْ\"\n جاء واحد من الصحابة اسمه حنظلة بن أبي عامر ،وهو ابن أبي عامر الراهب إللي رسول الله ﷺ سماه أبو عامر الفاسق وخرج من المدينة، فاكرين\nجاءه ليستأذنه إنه يبيت عند زوجته الليلة دي ويأتي تاني يوم الصبح ويكون مع الجيش ،\nوكان تزوج من جميلة بنت عبد الله بن أبي بن سلول، يعني يوم العرس كان يوم الجمعة يوم الإستعداد والتجهيز لغزوة أحد، \nفأذن له رسول الله ﷺ بإنه يبيت عندها الليلة دي، إللي احنا بنسميها ليلة الدخلة\n☆والله الناس دي فعلا غريبة\nعادي كده يتزوجوا قبل المعركة على طول ومن غير فرح ولا عزومات ولا أي حاجة،\nطيب المرأة مش خايفة مثلا إن زوجها يموت وتترمل وهي لسه في عز شبابها\nولّا زوجها ده مش خايف إنه يموت ويسيب مراته وراه،\nطيب عبد الله بن أبي بن سلول كان عادي الموضوع عنده إنه يزوج بنته لواحد ممكن يموت وبنته تبقى أرملة\nأنا مش عارف أتعجب من حياتنا إللي بقت صعبة والناس مصعبين على نفسهم كل حاجة،\nولّا أتعجب من سلاسة وسهولة مجتمع الصحابة \nالمهم،\nراح حنظلة وبات عند عروسه ودخل بها، وأرسلت لأربعة من أهلها تشهدهم إن حنظلة دخل بها،\nفاستغربوا ليه هي عملت كده، فقالت لهم إنها شافت رؤيا إن السماء انشقت ودخل فيها حنظلة وأطبقت عليه،\nيعني اتقفلت عليه.\nفهي كانت عايزة يكون في شهود على دخول حنظلة بها عشان متحطش نفسها في موضع تهمة \nلما جاء الصباح وصلى حنظلة الصبح والمفروض إنه يتجهز للخروج للجهاد، أَجْنَب من زوجته، فسمع المنادي ينادي للخروج للجهاد،\nفلبس بسرعة لبس الحرب ولم يغتسل وانطلق نحو الجيش وسار معهم لأرض المعركة،\nوكان من إللي خرج للجهاد مع رسول الله ﷺ عبد الله بن حرام صاحب عمرو بن الجموح وأخو زوجته،\nوكان عبد الله بن حرام عنده ولد واحد اسمه جابر وتسع بنات، وعبد الله بن حرام وابنه جابر من السابقين إلى الإسلام\n وحَضرَا بيعة العقبة الثانية، وحضر عبد الله بن حرام غزوة بدر،\nفقال عبد الله بن حرام لابنه جابر ليلة الخروج للجهاد :\nأرجو أن أكون في أول من يُصاب غدا، فأوصيك ببناتي خيرا\nيعني بيتمنى إنه أول واحد يُقتل في سبيل الله، فبيوصّيه على إخواته البنات،\nخرج رسول الله ﷺ على رأس جيش المسلمين معاه أبو بكر وعمر وعثمان وعلي ومصعب وحمزة وسعد بن الربيع،\nإللي كان رسول الله ﷺ آخى بينه وبين عبد الرحمن بن عوف، إللي كان له زوجتين وقال لعبد الرحمن شوف إللي تعجبك أطلقها وتتزوجها، فاكرين\nوغيرهم من الصحابة، وصلت الأخبار لرسول الله ﷺ إن المشركين خيّموا عند جبل أحد قريب من المدينة، \nفتوجه رسول الله ﷺ بالجيش ناحية أُحد ومشي من وسط المزارع إللي كانت حول المدينة عشان المشركين ميكتشفوش جيش المسلمين،\nولما قرب جيش المسلمين من أرض أُحد حصلت كارثة\nعبد الله بن أبي بن سلول قال:\nأنا مش موافق على القتال في أرض أُحد، والقتال في المدينة أحسن، ومش هيحصل هنا قتال، فأنا راجع إلى المدينة فارجعوا معي\nفانسحب معاه ثلاثمائة من الجيش كلهم من النافقين، والجيش أصلا كله ألف، وبقي القليل من المنافقين في الجيش مع رسول الله ﷺ، \nيعني انسحب بثلث الجيش تقريبا، والمشركين عددهم ثلاثة آلاف، يعني عددهم أد عدد المسلمين ثلاث مرات تقريبا\nعبد الله بن حرام وقف وحاول يمنعهم وقال لهم :\nتعالوا قاتلوا في سبيل الله أو دافعوا حتى\nفقالوا : مفيش قتال هيحصل، ولو احنا عارفين إن في قتال كنا قعدنا قاتلنا معكم\nفحاول يقنعهم وهم مش راضيين، فقال لهم: \nأبعدكم الله يا أعداء الله\n الله سيغني عنكم نبيه \nيعني كأنه بيقول لهم غوروا في داهية مش عايزينكم معانا\nوفيهم نزل قول الله :\n\"وَقِيلَ لَهُمْ تَعَالَوْا قَاتِلُوا فِي سَبِيلِ اللَّهِ أَوِ ادْفَعُوا ۖ قَالُوا لَوْ نَعْلَمُ قِتَالًا لَّاتَّبَعْنَاكُمْ ۗ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَانِ ۚ يَقُولُونَ بِأَفْوَاهِهِم مَّا لَيْسَ فِي قُلُوبِهِمْ ۗ وَاللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ \"\nطبعا احنا ممكن نفكر إن كده في خسارة للمسلمين، لكن بالعكس بقى ده كان مكسب كبير جدا للمسلمين \nلأن وجود المنافقين إللي بيظهروا الإيمان وقلوبهم مليانة كفر في جيش المسلمين مضر جدا للمسلمين،\nممكن يقولوا رأي فاسد ويثيروا الشبهات بين المؤمنين تخليهم يترددوا في القتال،\nأو إنهم يرسلوا بخطط المسلمين للمشركين، وفعلا انسحاب عبد الله بن أبي بن سلول ومعاه المنافقين أثّر على بعض المسلمين الصادقين،\nلدرجة إن في ناس منهم قالوا احنا نرجع المدينة ونقاتل فيها أحسن وحتى ده كان رأي رسول الله ﷺ، وعددنا أقل من عدد المشركين فالأحسن إننا نرجع\nفوقف رسول الله ﷺ ومعاه الصحابة وقعدوا يقنعوهم لحد ما ثبتوا مع رسول الله ﷺ بسبب صدق إيمانهم،\n\"إِذْ هَمَّت طَّائِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَاللَّهُ وَلِيُّهُمَا ۗ وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُون\"\nعلى فكرة يا جماعة الصحابة مكنوش يعرفوا موضوع المنافقين ده خالص \nيعني مكنوش يعرفوا إن عبد الله بن أبي بن سلول منافق لسه ولا أي حاجة عشان كده اتأثروا بالموقف،\nزينا كده بالضبط، \nنشوف ناس ظاهرها الصلاح ونلاقي منهم مواقف عجيبة بتحصل، بنبقى مستغربين من تصرفاتهم فبنحسن الظن فيهم وبناخد بالنا لما نتعامل معاهم وخلاص ،لأننا معندناش دليل أو وحي زي أيام رسول الله ﷺ \nوده من الحكمة الإلهية إن المسلمين معرفوش عن المنافقين إلا بعدين، عشان ربنا يورينا إزاي نتعامل مع المنافقين بصفة عامة واحنا مش متأكدين منهم أوي ولا معانا دليل غير تصرفاتهم\nدخل رسول الله ﷺ أرض أحد وبدأ يختار المكان إللي هيكون فيه معسكر المسلمين،\nاختار رسول الله ﷺ مكان في منتهى العبقرية\nاختار إن الجيش يكون في ظهره وعلى يمينه جبل أحد، ودي تُعتبر حماية طبيعية للجيش،\nوالأرض إللي كان واقف عليها أرض مرتفعة نسبيا، في حين إن المشركين كانوا على أرض منخفضة وده يعطي المسلمين القدرة على القتال،\nلكن المكان ده كان في ثغرة قاتلة \nكان في جبل صغير على يسار جيش المسلمين، لو حصل إن المشركين إلتفوا من وراء الجبل ده، يقدروا يكونوا وراء جيش المسلمين ويبقى المسلمين بين فكّي كماشة،\nيعني يتحاصر المسلمين من جيش أمامي وجيش خلفي وساعتها هتبقى كارثة على المسلمين\nالمكان كويس ماعدا موضوع الجبل ده، طيب إيه الحل\nاختار رسول الله ﷺ خمسين واحد من الصحابة من أمهر الرُّمَاة، وجعل قائدهم أمهر واحد فيهم وهو عبد الله بن جبير من الأوس،\nوالرماة يعني إللي بيرموا السهام ويصيبوا بها الهدف\nأخذ رسول الله ﷺ الرماة وطلع معاهم على الجبل وبدأ يشرح لهم يعملوا إيه ويوضح لهم مهمتهم الخطيرة جدا، \nفقال لهم أوامر واضحة وصريحة جدا بحيث إن محدش يفهم غلط ولا يتأوّل الكلام\nقال لقائدهم عبد الله بن جبير:\nانْضَح عنا الخيل بالنبل، لا يأتونا من خلفنا \nيعني مهمتك إنت وإللي معاك إن أي خيل تيجي تهجم على جيش المسلمين من ناحية الجبل الصغير ده تدفعوهم بالنبال، بالسهام يعني،\nإن كانت لنا أو علينا فاثبت مكانك، يعني لو شفتونا غلبناهم خليكم مكانكم، لو شفتونا انهزمنا خليكم مكانكم محدش يسيب الجبل،\nعشان المسلمين ميخسروش الحرب بسببكم،\nبدأ رسول الله ﷺ يوجه كلامه للجميع.. للقائد وباقي الرماة قال :\nلو رأيتمونا تخطفُنا الطير فلا تبرحوا مكانكم هذا حتى أرسل إليكم\nيعني لو شفتونا انهزمنا لدرجة إن الطير بقت تأكل جثث المسلمين متسبوش مكانكم لحد ما أنا أقول لكم،\nلو شفتونا انتصرنا على القوم وغالبناهم محدش يسيب مكانه لحد ما أقول لكم\nشوفوا رسول الله ﷺ بيؤكد عليهم إزاي لأن المكان ده مهم جدا، أي خلل هيحصل فيه كل المسلمين هيتأثروا به\nنزل رسول الله ﷺ من على جبل الرماة واتجه ناحية جيش المسلمين وبدأ يُحفّز الناس للقتال ويذكرهم بالجنة،\nويرفع من روحهم المعنوية،\nوأشعل روح التنافس بينهم فمسك سيفه وقال :\nمن يأخذ هذا السيف بحقه؟\nفكل واحد بدأ يقول أنا أنا ..علي بن أبي طالب..عمر بن الخطاب..الزبير بن العوام..وغيرهم،\nورسول الله ﷺ مش راضي يعطيه لأحد، ويُعيد من يأخذ هذا السيف بحقه، وهم يقولوا أنا...أنا...\nفقال أبو دجانة الأنصاري واسمه سِمَاك بن خَرَشة : \nوما حقه يا رسول الله\nقال رسول الله ﷺ: أن تضرب به وجوه العدو حتى ينحني\nفقال أبو دجانة بكل قوة : أنا آخذه يا رسول الله\nوأخذ السيف وقام وأخرج من جيبه عصابة رأس لونها أحمر ،زي شريطة كده \nوربطها على رأسه، فقال الأنصار :\nأبو دجانة ربط عصابة الموت\nوكان معروف عن أبي دجانة إنه لما يربط العصابة دي يبقى عايز الموت\nوبدأ يمشي متبختر يعني بيتمختر في مشيته، زي ما بنقول فرحان بنفسه بين صفوف المسلمين والمشركين،\nفقال رسول الله ﷺ: المشية دي يبغضها الله ورسوله إلا في هذا الموطن\nيعني في موطن الجهاد عادي إن الإنسان يظهر القوة والعزم والثقة بالنفس أمام المشركين غيظا لهم \nالزبير بن العوام قال إنه مشي وراء أبو دجانة عشان يشوفه هيعمل إيه بسيف رسول الله ﷺ،\nدي كانت الترتيبات في جيش المسلمين، نروح نشوف ترتيبات جيش المشركين وهنشوف أبو دجانة عمل إيه بسيف رسول الله ﷺ المرة الجاية إن شاء الله"}]);
